import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';
import tailwindcss from '@tailwindcss/vite';

// https://vitejs.dev/config/
export default defineConfig({
  plugins: [
    react(),
    tailwindcss(),
  ],
  server: {
    port: 5173,
    proxy: {
      '/api': {
        target: 'http://localhost:3001',
        changeOrigin: true,
      },
    },
  },
});

export type ExpertiseArea =
  | 'Finance'
  | 'Healthcare'
  | 'Data Analysis'
  | 'Operations'
  | 'Legal'
  | 'Security'
  | string;

export interface Contributor {
  id: string;
  name: string;
  email: string;
  title: string;
  avatar: string;
  expertise: string[];
  status: 'available' | 'busy' | 'offline';
  maxActiveTasks: number;
}

export type TaskState =
  | 'pending'
  | 'routing'
  | 'assigned'
  | 'accepted'
  | 'declined'
  | 'failed'
  | 'recovered'
  | 'cancelled';

export type ActorType = 'system' | 'routing_engine' | 'operator' | 'contributor';

export type ActionType =
  | 'TASK_CREATED'
  | 'ROUTING_STARTED'
  | 'ROUTING_HANG_SIMULATED'
  | 'CONTRIBUTOR_MATCHED'
  | 'NO_MATCH_FOUND'
  | 'OPERATOR_CANCEL_ROUTING'
  | 'OPERATOR_MANUAL_ASSIGN'
  | 'OPERATOR_FORCE_REROUTE'
  | 'OPERATOR_RECOVER'
  | 'CONTRIBUTOR_ACCEPTED'
  | 'CONTRIBUTOR_DECLINED';

export interface TaskHistoryEntry {
  id: string;
  taskId: string;
  timestamp: string; // ISO string
  actor: ActorType;
  actorName: string;
  action: ActionType;
  previousState: TaskState | null;
  newState: TaskState;
  details: string;
  metadata?: Record<string, any>;
}

export interface Task {
  id: string;
  title: string;
  description: string;
  expertiseRequired: string;
  state: TaskState;
  activeAssigneeId: string | null;
  activeAssignee?: Contributor | null;
  createdAt: string; // ISO string
  updatedAt: string; // ISO string
  assignedAt: string | null;
  routingStartedAt: string | null;
  routingDurationSec: number | null;
  isStuckSimulated: boolean;
  routingAttempt: number;
  history: TaskHistoryEntry[];
}

export interface SystemStats {
  totalTasks: number;
  pending: number;
  routing: number;
  stuckRouting: number;
  assigned: number;
  accepted: number;
  declined: number;
  failed: number;
  recovered: number;
  cancelled: number;
  totalContributors: number;
  availableContributors: number;
}

import { DatabaseSync } from 'node:sqlite';
import path from 'node:path';
import fs from 'node:fs';
import { fileURLToPath } from 'node:url';
import { Contributor, Task, TaskHistoryEntry, SystemStats, TaskState } from './types.js';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const DATA_DIR = path.resolve(__dirname, '../data');
if (!fs.existsSync(DATA_DIR)) {
  fs.mkdirSync(DATA_DIR, { recursive: true });
}

const DB_PATH = path.join(DATA_DIR, 'routing_system.db');
export const db = new DatabaseSync(DB_PATH);

// Initialize Tables
export function initDatabase() {
  db.exec(`
    CREATE TABLE IF NOT EXISTS contributors (
      id TEXT PRIMARY KEY,
      name TEXT NOT NULL,
      email TEXT NOT NULL,
      title TEXT NOT NULL,
      avatar TEXT NOT NULL,
      expertise TEXT NOT NULL,
      status TEXT NOT NULL DEFAULT 'available',
      maxActiveTasks INTEGER NOT NULL DEFAULT 2
    );

    CREATE TABLE IF NOT EXISTS tasks (
      id TEXT PRIMARY KEY,
      title TEXT NOT NULL,
      description TEXT NOT NULL,
      expertiseRequired TEXT NOT NULL,
      state TEXT NOT NULL,
      activeAssigneeId TEXT,
      createdAt TEXT NOT NULL,
      updatedAt TEXT NOT NULL,
      assignedAt TEXT,
      routingStartedAt TEXT,
      routingDurationSec REAL,
      isStuckSimulated INTEGER NOT NULL DEFAULT 0,
      routingAttempt INTEGER NOT NULL DEFAULT 1,
      FOREIGN KEY (activeAssigneeId) REFERENCES contributors(id)
    );

    CREATE TABLE IF NOT EXISTS task_history (
      id TEXT PRIMARY KEY,
      taskId TEXT NOT NULL,
      timestamp TEXT NOT NULL,
      actor TEXT NOT NULL,
      actorName TEXT NOT NULL,
      action TEXT NOT NULL,
      previousState TEXT,
      newState TEXT NOT NULL,
      details TEXT NOT NULL,
      metadata TEXT,
      FOREIGN KEY (taskId) REFERENCES tasks(id) ON DELETE CASCADE
    );

    CREATE INDEX IF NOT EXISTS idx_tasks_state ON tasks(state);
    CREATE INDEX IF NOT EXISTS idx_tasks_expertise ON tasks(expertiseRequired);
    CREATE INDEX IF NOT EXISTS idx_history_taskId ON task_history(taskId);
  `);

  seedDefaultContributors();
  seedSampleTasksIfEmpty();
}

