  updateTask,
  addHistoryEntry,
  getContributorsByExpertise,
  getAllContributors,
  getSystemStats,
} from './db.js';
import { eventStream } from './eventStream.js';
import { Contributor, Task } from './types.js';

interface ActiveJob {
  jobId: string;
  taskId: string;
  startedAt: number;
  durationMs: number;
  timerHandle?: NodeJS.Timeout;
  isStuck: boolean;
}

export class RoutingEngine {
  private activeJobs: Map<string, ActiveJob> = new Map(); // taskId -> ActiveJob

  // Configuration for simulation
  public minDurationMs: number = 5000;
  public maxDurationMs: number = 20000;
  public stuckProbability: number = 0.20; // 20% edge case

  constructor() {}

  /**
   * Start asynchronous background routing for a task
   */
  public startRouting(
    taskId: string,
    options?: {
      forceStuck?: boolean;
      customDurationMs?: number;
      actorName?: string;
    }
  ): { jobId: string; isStuck: boolean; durationSec: number | null } {
    const task = getTaskById(taskId);
    if (!task) {
      throw new Error(`Task with id ${taskId} not found`);
    }

    // Cancel any existing job for this task if currently running
    this.abortRunningJob(taskId, 'Replacing with new routing request');

    const jobId = `job_${Date.now()}_${randomUUID().slice(0, 8)}`;
    const now = new Date();

    // Determine if this request will hit the 20% stuck edge case
    // If options explicitly dictate, follow that (e.g. for deterministic testing), otherwise 20% random
    const willHang =
      options?.forceStuck !== undefined
        ? options.forceStuck
        : Math.random() < this.stuckProbability;

    // Normal duration is between 5 and 20 seconds
    const durationMs =
      options?.customDurationMs !== undefined
        ? options.customDurationMs
        : Math.floor(Math.random() * (this.maxDurationMs - this.minDurationMs + 1)) +
          this.minDurationMs;
    const durationSec = Number((durationMs / 1000).toFixed(1));

    const previousState = task.state;
    const newState = 'routing';

    // Update Task in Database
    updateTask(taskId, {
      state: newState,
      activeAssigneeId: null,
      routingStartedAt: now.toISOString(),
      routingDurationSec: willHang ? null : durationSec,
      isStuckSimulated: willHang,
      assignedAt: null,
    });

    // Audit log: Routing Started
    addHistoryEntry({
      id: randomUUID(),
      taskId,
      timestamp: now.toISOString(),
      actor: 'routing_engine',
      actorName: 'Routing Engine',
      action: 'ROUTING_STARTED',
      previousState,
      newState,
      details: willHang
        ? `Routing request initiated in background for expertise '${task.expertiseRequired}' (Attempt #${task.routingAttempt}).`
        : `Routing request initiated in background for expertise '${task.expertiseRequired}' (estimated ${durationSec}s search window).`,
      metadata: {
        jobId,
        expertiseRequired: task.expertiseRequired,
        attempt: task.routingAttempt,
      },
    });

    if (willHang) {
      // 20% edge case: Never returns.
      // Record in audit log so operator / auditor can inspect the stuck condition
      addHistoryEntry({
        id: randomUUID(),
        taskId,
        timestamp: new Date().toISOString(),
        actor: 'routing_engine',
        actorName: 'Routing Engine',
        action: 'ROUTING_HANG_SIMULATED',
        previousState: 'routing',
        newState: 'routing',
        details:
          'Simulated 20% edge case: Connection to background worker dropped without error or completion. This request will hang indefinitely until an operator intervenes.',
        metadata: {
          jobId,
          isStuck: true,
        },
      });

      const job: ActiveJob = {
        jobId,
        taskId,
        startedAt: Date.now(),
        durationMs: Infinity,
        isStuck: true,
      };
      this.activeJobs.set(taskId, job);

      // Broadcast update
      this.broadcastTaskChanged(taskId);

      return { jobId, isStuck: true, durationSec: null };
    }

    // Normal routing request (80%): returns in 5-20 seconds
    const timerHandle = setTimeout(() => {
      this.completeRouting(taskId, jobId, durationSec);
    }, durationMs);

    const job: ActiveJob = {
      jobId,
      taskId,
      startedAt: Date.now(),
      durationMs,
      timerHandle,
      isStuck: false,
    };
    this.activeJobs.set(taskId, job);

    // Broadcast update
    this.broadcastTaskChanged(taskId);

    return { jobId, isStuck: false, durationSec };
  }

  /**
   * Called when the background matching completes normally
   */
  private completeRouting(taskId: string, jobId: string, durationSec: number) {
    const job = this.activeJobs.get(taskId);
    if (!job || job.jobId !== jobId) {
      // Job was cancelled or already replaced
      return;
    }
    this.activeJobs.delete(taskId);

    const task = getTaskById(taskId);
    if (!task) return;

    // Safety check: ensure task is still in routing state (no operator intervened in the meantime)
    if (task.state !== 'routing') {
      return;
    }

    const matchingContributors = getContributorsByExpertise(task.expertiseRequired);

    if (matchingContributors.length > 0) {
      // Pick one eligible contributor
      // For fair distribution, pick random or contributor with least active tasks
      const allTasks = task; // placeholder
      const selected = this.selectBestContributor(matchingContributors);

      const assignedAt = new Date().toISOString();
      updateTask(taskId, {
        state: 'assigned',
        activeAssigneeId: selected.id,
        assignedAt,
        isStuckSimulated: false,
      });

      addHistoryEntry({
        id: randomUUID(),
        taskId,
        timestamp: assignedAt,
        actor: 'routing_engine',
        actorName: 'Routing Engine',
        action: 'CONTRIBUTOR_MATCHED',
        previousState: 'routing',
        newState: 'assigned',
        details: `Routing engine matched eligible contributor ${selected.name} (${selected.title}) for expertise '${task.expertiseRequired}' after ${durationSec}s.`,
        metadata: {
          contributorId: selected.id,
          contributorName: selected.name,
          matchingCandidatesCount: matchingContributors.length,
          durationSec,
        },
      });
    } else {
      // No match found
      const failedAt = new Date().toISOString();
      updateTask(taskId, {
        state: 'failed',
        activeAssigneeId: null,
        isStuckSimulated: false,
      });

      addHistoryEntry({
        id: randomUUID(),
        taskId,
        timestamp: failedAt,
        actor: 'routing_engine',
        actorName: 'Routing Engine',
        action: 'NO_MATCH_FOUND',
        previousState: 'routing',
        newState: 'failed',
        details: `Routing engine finished after ${durationSec}s: No contributor found with required expertise '${task.expertiseRequired}'. Requires operator recovery or manual assignment.`,
        metadata: {
          expertiseRequired: task.expertiseRequired,
          durationSec,
        },
      });
    }

    this.broadcastTaskChanged(taskId);
  }

  /**
   * Pick eligible contributor from matching candidates
   */
  private selectBestContributor(candidates: Contributor[]): Contributor {
    // Pick randomly among matching candidates
    const index = Math.floor(Math.random() * candidates.length);
    return candidates[index];
  }

  /**
   * Aborts any running background timer for a task
   */
  private abortRunningJob(taskId: string, reason: string): boolean {
    const job = this.activeJobs.get(taskId);
    if (!job) return false;

    if (job.timerHandle) {
      clearTimeout(job.timerHandle);
    }
    this.activeJobs.delete(taskId);
    return true;
  }

  /**
   * Operator Intervenes: Cancel / Abort routing in progress
   */
  public cancelRouting(taskId: string, operatorName: string = 'Human Operator', reason?: string): Task {
    const task = getTaskById(taskId);
    if (!task) throw new Error(`Task ${taskId} not found`);

    const wasRunning = this.abortRunningJob(taskId, reason || 'Operator cancelled routing');
    const previousState = task.state;
    const newState = 'cancelled';

    updateTask(taskId, {
      state: newState,
      isStuckSimulated: false,
    });

    addHistoryEntry({
      id: randomUUID(),
      taskId,
      timestamp: new Date().toISOString(),
      actor: 'operator',
      actorName: operatorName,
      action: 'OPERATOR_CANCEL_ROUTING',
      previousState,
      newState,
      details: `Operator cancelled routing in progress.${reason ? ` Note: "${reason}"` : ''} Background job was aborted.`,
      metadata: {
        wasRunning,
        reason,
      },
    });

    this.broadcastTaskChanged(taskId);
    return getTaskById(taskId)!;
  }

  /**
   * Operator Intervenes: Manually assign contributor at any time
   */
  public manualAssign(
    taskId: string,
    contributorId: string,
    operatorName: string = 'Human Operator',
    reason?: string
  ): Task {
    const task = getTaskById(taskId);
    if (!task) throw new Error(`Task ${taskId} not found`);

    const contributor = getAllContributors().find((c) => c.id === contributorId);
    if (!contributor) throw new Error(`Contributor ${contributorId} not found`);

    // Abort any active routing job
    this.abortRunningJob(taskId, 'Operator manually assigned contributor');

    const previousState = task.state;
    const newState = 'assigned';
    const assignedAt = new Date().toISOString();

    const matchesExpertise = contributor.expertise
      .map((e) => e.toLowerCase())
      .includes(task.expertiseRequired.toLowerCase());

    updateTask(taskId, {
      state: newState,
      activeAssigneeId: contributor.id,
      assignedAt,
      isStuckSimulated: false,
    });

    addHistoryEntry({
      id: randomUUID(),
      taskId,
      timestamp: assignedAt,
      actor: 'operator',
      actorName: operatorName,
      action: 'OPERATOR_MANUAL_ASSIGN',
      previousState,
      newState,
      details: `Operator manually assigned task to ${contributor.name} (${contributor.title}).${
        matchesExpertise ? ' [Matches Required Expertise]' : ' [Operator Expertise Override]'
      }${reason ? ` Note: "${reason}"` : ''}`,
      metadata: {
        contributorId: contributor.id,
        contributorName: contributor.name,
        matchesExpertise,
        reason,
      },
    });

    this.broadcastTaskChanged(taskId);
    return getTaskById(taskId)!;
  }

  /**
   * Operator Intervenes: Recover a failed or declined task
   */
  public recoverTask(
    taskId: string,
    action: 'reroute' | 'manual',
    options?: {
      contributorId?: string;
      operatorName?: string;
      reason?: string;
      customDurationMs?: number;
      forceStuck?: boolean;
    }
  ): Task {
    const task = getTaskById(taskId);
    if (!task) throw new Error(`Task ${taskId} not found`);

    const operatorName = options?.operatorName || 'Human Operator';
    const previousState = task.state;

    if (action === 'reroute') {
      const nextAttempt = task.routingAttempt + 1;
      updateTask(taskId, {
        state: 'recovered',
        activeAssigneeId: null,
        routingAttempt: nextAttempt,
      });

      addHistoryEntry({
        id: randomUUID(),
        taskId,
        timestamp: new Date().toISOString(),
        actor: 'operator',
        actorName: operatorName,
        action: 'OPERATOR_RECOVER',
        previousState,
        newState: 'recovered',
        details: `Operator recovered task from '${previousState}' state and initiated re-routing (Attempt #${nextAttempt}).${
          options?.reason ? ` Note: "${options.reason}"` : ''
        }`,
        metadata: {
          previousState,
          nextAttempt,
          reason: options?.reason,
        },
      });

      this.broadcastTaskChanged(taskId);

      // Start routing anew
      this.startRouting(taskId, {
        forceStuck: options?.forceStuck,
        customDurationMs: options?.customDurationMs,
        actorName: operatorName,
      });

      return getTaskById(taskId)!;
    } else {
      // Manual recovery
      if (!options?.contributorId) {
        throw new Error('contributorId is required for manual recovery');
      }
      return this.manualAssign(
        taskId,
        options.contributorId,
        operatorName,
        options?.reason || 'Task recovered via manual assignment'
      );
    }
  }

  /**
   * Simulate Contributor: Accept assignment
   */
  public contributorAccept(taskId: string, contributorId?: string): Task {
    const task = getTaskById(taskId);
    if (!task) throw new Error(`Task ${taskId} not found`);
    if (task.state !== 'assigned') {
      throw new Error(`Cannot accept task in state '${task.state}'. Task must be 'assigned'.`);
    }

    const assignee = task.activeAssignee;
    const actorName = assignee ? assignee.name : 'Contributor';
    const previousState = task.state;
    const newState = 'accepted';

    updateTask(taskId, {
      state: newState,
    });

    addHistoryEntry({
      id: randomUUID(),
      taskId,
      timestamp: new Date().toISOString(),
      actor: 'contributor',
      actorName,
      action: 'CONTRIBUTOR_ACCEPTED',
      previousState,
      newState,
      details: `Contributor ${actorName} accepted the assignment. Routing is finalized.`,
      metadata: {
        contributorId: assignee?.id,
        contributorName: actorName,
      },
    });

    this.broadcastTaskChanged(taskId);
    return getTaskById(taskId)!;
  }

  /**
   * Simulate Contributor: Decline assignment
   */
  public contributorDecline(
    taskId: string,
    reason: string = 'Capacity limitation or scheduling conflict'
  ): Task {
    const task = getTaskById(taskId);
    if (!task) throw new Error(`Task ${taskId} not found`);
    if (task.state !== 'assigned') {
      throw new Error(`Cannot decline task in state '${task.state}'. Task must be 'assigned'.`);
    }

    const assignee = task.activeAssignee;
    const actorName = assignee ? assignee.name : 'Contributor';
    const previousState = task.state;
    const newState = 'declined';

    updateTask(taskId, {
      state: newState,
      activeAssigneeId: null, // Clear active assignee so task can be reassigned
    });

    addHistoryEntry({
      id: randomUUID(),
      taskId,
      timestamp: new Date().toISOString(),
      actor: 'contributor',
      actorName,
      action: 'CONTRIBUTOR_DECLINED',
      previousState,
      newState,
      details: `Contributor ${actorName} declined the assignment: "${reason}". Task requires operator recovery.`,
      metadata: {
        contributorId: assignee?.id,
        contributorName: actorName,
        reason,
      },
    });

    this.broadcastTaskChanged(taskId);
    return getTaskById(taskId)!;
  }

  /**
   * Helper to broadcast task updates and system stats
   */
  private broadcastTaskChanged(taskId: string) {
    const task = getTaskById(taskId);
    const stats = getSystemStats();
    eventStream.broadcast('TASK_UPDATED', { task, stats });
  }

  public getActiveJobs(): Array<{ taskId: string; jobId: string; elapsedSec: number; isStuck: boolean }> {
    const now = Date.now();
    const result = [];
    for (const [taskId, job] of this.activeJobs.entries()) {
      result.push({
        taskId,
        jobId: job.jobId,
        elapsedSec: Math.floor((now - job.startedAt) / 1000),
        isStuck: job.isStuck,
      });
    }
    return result;
  }
}

export const routingEngine = new RoutingEngine();

import express, { Request, Response } from 'express';
import cors from 'cors';
import { randomUUID } from 'node:crypto';
import path from 'node:path';
import fs from 'node:fs';
import { fileURLToPath } from 'node:url';

import {
  initDatabase,
  getAllTasks,
  getTaskById,
  createTaskDirect,
  getAllContributors,
  getContributorById,
  saveContributor,
  getTaskHistory,
  getSystemStats,
  resetDatabase,
  addHistoryEntry,
} from './db.js';
import { routingEngine } from './routingEngine.js';
import { eventStream } from './eventStream.js';
import { Task, TaskState } from './types.js';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const app = express();
const PORT = process.env.PORT ? parseInt(process.env.PORT, 10) : 3001;

app.use(cors());
app.use(express.json());

// Initialize SQLite database
initDatabase();

// ----------------- SSE Real-time Stream -----------------
app.get('/api/events', (req: Request, res: Response) => {
  res.writeHead(200, {
    'Content-Type': 'text/event-stream',
    'Cache-Control': 'no-cache',
    Connection: 'keep-alive',
  });

  const clientId = `client_${Date.now()}_${randomUUID().slice(0, 6)}`;
  eventStream.addClient(clientId, res);
});

// ----------------- Tasks Endpoints -----------------

// 1. Get all tasks
app.get('/api/tasks', (req: Request, res: Response) => {
  const { state, expertise, search } = req.query;
  let tasks = getAllTasks();

  if (state && typeof state === 'string' && state !== 'all') {
    tasks = tasks.filter((t) => t.state === state);
  }
  if (expertise && typeof expertise === 'string' && expertise !== 'all') {
    tasks = tasks.filter(
      (t) => t.expertiseRequired.toLowerCase() === expertise.toLowerCase()
    );
  }
  if (search && typeof search === 'string') {
    const q = search.toLowerCase();
    tasks = tasks.filter(
      (t) =>
        t.title.toLowerCase().includes(q) ||
        t.id.toLowerCase().includes(q) ||
        t.description.toLowerCase().includes(q) ||
        (t.activeAssignee && t.activeAssignee.name.toLowerCase().includes(q))
    );
  }

  res.json({ tasks, stats: getSystemStats() });
});

// 2. Get task by ID
app.get('/api/tasks/:id', (req: Request, res: Response) => {
  const task = getTaskById(req.params.id);
  if (!task) {
    res.status(404).json({ error: 'Task not found' });
    return;
  }
  res.json({ task });
});

// 3. Create task & optionally submit for routing
app.post('/api/tasks', (req: Request, res: Response) => {
  try {
    const {
      title,
      description,
      expertiseRequired,
      autoRoute = true,
      forceStuck,
      customDurationMs,
      operatorName = 'Operator',
    } = req.body;

    if (!title || !expertiseRequired) {
      res.status(400).json({ error: 'Title and expertiseRequired are required' });
      return;
    }

    const taskId = `TASK-${Date.now().toString().slice(-4)}`;
    const now = new Date().toISOString();

    const initialState: TaskState = autoRoute ? 'pending' : 'pending';

    createTaskDirect({
      id: taskId,
      title: title.trim(),
      description: (description || '').trim(),
      expertiseRequired: expertiseRequired.trim(),
      state: initialState,
      activeAssigneeId: null,
      createdAt: now,
      updatedAt: now,
      routingAttempt: 1,
      isStuckSimulated: false,
    });

    addHistoryEntry({
      id: randomUUID(),
      taskId,
      timestamp: now,
      actor: 'operator',
      actorName: operatorName,
      action: 'TASK_CREATED',
      previousState: null,
      newState: 'pending',
      details: `Task '${title}' created with requirement: ${expertiseRequired}.`,
      metadata: { autoRoute },
    });

    let task = getTaskById(taskId)!;

    if (autoRoute) {
      routingEngine.startRouting(taskId, {
        forceStuck,
        customDurationMs,
        actorName: operatorName,
      });
      task = getTaskById(taskId)!;
    }

    eventStream.broadcast('TASK_CREATED', { task, stats: getSystemStats() });

    res.status(201).json({ task, message: 'Task created successfully' });
  } catch (err: any) {
    res.status(500).json({ error: err.message });
  }
});

// 4. Manually trigger routing for a pending task
app.post('/api/tasks/:id/route', (req: Request, res: Response) => {
  try {
    const { id } = req.params;
    const { forceStuck, customDurationMs, operatorName = 'Operator' } = req.body;
    const task = getTaskById(id);
    if (!task) {
      res.status(404).json({ error: 'Task not found' });
      return;
    }

    const result = routingEngine.startRouting(id, {
      forceStuck,
      customDurationMs,
      actorName,
    });

    res.json({
      task: getTaskById(id),
      routingInfo: result,
      message: 'Routing initiated in background',
    });
  } catch (err: any) {
    res.status(500).json({ error: err.message });
  }
});

// 5. Operator Intervene in assignment/routing
app.post('/api/tasks/:id/intervene', (req: Request, res: Response) => {
  try {
    const { id } = req.params;
    const { action, contributorId, operatorName = 'Operator', reason } = req.body;

    const task = getTaskById(id);
    if (!task) {
      res.status(404).json({ error: 'Task not found' });
      return;
    }

    let updated: Task;

    switch (action) {
      case 'cancel_routing': {
        updated = routingEngine.cancelRouting(id, operatorName, reason);
        break;
      }
      case 'manual_assign': {
        if (!contributorId) {
          res.status(400).json({ error: 'contributorId required for manual_assign' });
          return;
        }
        updated = routingEngine.manualAssign(id, contributorId, operatorName, reason);
        break;
      }
      case 'force_reroute': {
        routingEngine.cancelRouting(id, operatorName, 'Operator triggered force re-route');
        routingEngine.startRouting(id, { actorName: operatorName });
        updated = getTaskById(id)!;
        break;
      }
      default:
        res.status(400).json({ error: `Unknown intervention action: ${action}` });
        return;
    }

    res.json({ task: updated, message: `Operator intervention '${action}' executed.` });
  } catch (err: any) {
    res.status(500).json({ error: err.message });
  }
});

// 6. Operator Recover a failed or declined task
app.post('/api/tasks/:id/recover', (req: Request, res: Response) => {
  try {
    const { id } = req.params;
    const {
      action = 'reroute',
      contributorId,
      operatorName = 'Operator',
      reason,
      forceStuck,
      customDurationMs,
    } = req.body;

    const task = getTaskById(id);
    if (!task) {
      res.status(404).json({ error: 'Task not found' });
      return;
    }

    const updated = routingEngine.recoverTask(id, action, {
      contributorId,
      operatorName,
      reason,
      forceStuck,
      customDurationMs,
    });

    res.json({
      task: updated,
      message: `Task recovered via ${action}`,
    });
  } catch (err: any) {
    res.status(500).json({ error: err.message });
  }
});

// 7. Contributor Simulation: Accept or Decline
app.post('/api/tasks/:id/contributor-action', (req: Request, res: Response) => {
  try {
    const { id } = req.params;
    const { action, reason } = req.body;

    let updated: Task;
    if (action === 'accept') {
      updated = routingEngine.contributorAccept(id);
    } else if (action === 'decline') {
      updated = routingEngine.contributorDecline(id, reason);
    } else {
      res.status(400).json({ error: `Invalid action: ${action}. Must be 'accept' or 'decline'.` });
      return;
    }

    res.json({ task: updated, message: `Contributor action '${action}' recorded.` });
  } catch (err: any) {
    res.status(500).json({ error: err.message });
  }
});

// 8. Task History / Audit Log
app.get('/api/tasks/:id/history', (req: Request, res: Response) => {
  const { id } = req.params;
  const history = getTaskHistory(id);
  res.json({ history });
});

// 9. Contributors List & Details
app.get('/api/contributors', (req: Request, res: Response) => {
  const contributors = getAllContributors();
  const tasks = getAllTasks();

  // Attach active assignment counts
  const enriched = contributors.map((c) => {
    const activeTasks = tasks.filter(
      (t) =>
        t.activeAssigneeId === c.id &&
        (t.state === 'assigned' || t.state === 'accepted' || t.state === 'routing')
    );
    return {
      ...c,
      activeTaskCount: activeTasks.length,
      currentTasks: activeTasks.map((t) => ({ id: t.id, title: t.title, state: t.state })),
    };
  });

  res.json({ contributors: enriched });
});

// 10. Add or Update Contributor
app.post('/api/contributors', (req: Request, res: Response) => {
  try {
    const { id, name, email, title, avatar, expertise, status, maxActiveTasks } = req.body;
    if (!name || !expertise || !Array.isArray(expertise) || expertise.length === 0) {
      res.status(400).json({ error: 'Name and at least one expertise are required' });
      return;
    }

    const contributorId = id || `contrib_${Date.now().toString().slice(-4)}`;
    const contributor = {
      id: contributorId,
      name,
      email: email || `${name.toLowerCase().replace(/\s+/g, '.')}@system.io`,
      title: title || 'Specialist Contributor',
      avatar:
        avatar ||
        `https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?w=150&auto=format&fit=crop&q=80`,
      expertise,
      status: status || 'available',
      maxActiveTasks: maxActiveTasks || 2,
    };

    saveContributor(contributor);
    eventStream.broadcast('CONTRIBUTOR_UPDATED', { contributor });
    res.status(201).json({ contributor });
  } catch (err: any) {
    res.status(500).json({ error: err.message });
  }
});

// 11. System Statistics
app.get('/api/stats', (req: Request, res: Response) => {
  res.json({ stats: getSystemStats() });
});

// 12. Simulation Controls (Config & Info)
app.get('/api/simulation/config', (req: Request, res: Response) => {
  res.json({
    minDurationMs: routingEngine.minDurationMs,
    maxDurationMs: routingEngine.maxDurationMs,
    stuckProbability: routingEngine.stuckProbability,
    activeJobs: routingEngine.getActiveJobs(),
  });
});

app.post('/api/simulation/config', (req: Request, res: Response) => {
  const { minDurationMs, maxDurationMs, stuckProbability } = req.body;
  if (minDurationMs !== undefined) routingEngine.minDurationMs = Number(minDurationMs);
  if (maxDurationMs !== undefined) routingEngine.maxDurationMs = Number(maxDurationMs);
  if (stuckProbability !== undefined) routingEngine.stuckProbability = Number(stuckProbability);

  res.json({
    message: 'Simulation parameters updated',
    config: {
      minDurationMs: routingEngine.minDurationMs,
      maxDurationMs: routingEngine.maxDurationMs,
      stuckProbability: routingEngine.stuckProbability,
    },
  });
});

// 13. System Reset & Demo Seeding
app.post('/api/system/reset', (req: Request, res: Response) => {
  resetDatabase();
  eventStream.broadcast('SYSTEM_RESET', { stats: getSystemStats() });
  res.json({ message: 'Database reset to initial demo state', stats: getSystemStats() });
});

// Seed an instant live routing demo task (including one normal and one stuck)
app.post('/api/system/seed-demo-routing', (req: Request, res: Response) => {
  const { type = 'normal' } = req.body;
  const now = new Date().toISOString();
  const taskId = `TASK-LIVE-${Date.now().toString().slice(-4)}`;

  const isStuck = type === 'stuck';
  createTaskDirect({
    id: taskId,
    title: isStuck
      ? 'Complex Multi-Market Volatility Simulation'
      : 'Real-time Clinical Triage Data Reconciliation',
    description: isStuck
      ? 'High-frequency Monte Carlo risk analysis across global derivatives (Simulated 20% hanging request edge case).'
      : 'Reconcile patient intake stream across multiple diagnostic units.',
    expertiseRequired: isStuck ? 'Finance' : 'Healthcare',
    state: 'pending',
    createdAt: now,
    updatedAt: now,
    activeAssigneeId: null,
    isStuckSimulated: false,
    routingAttempt: 1,
  });

  addHistoryEntry({
    id: randomUUID(),
    taskId,
    timestamp: now,
    actor: 'operator',
    actorName: 'Operator',
    action: 'TASK_CREATED',
    previousState: null,
    newState: 'pending',
    details: `Task created for demonstration (${isStuck ? 'Demonstrating 20% stuck edge case' : 'Normal 5-20s routing'}).`,
  });

  routingEngine.startRouting(taskId, {
    forceStuck: isStuck,
  });

  res.json({ task: getTaskById(taskId) });
});

// Serve frontend in production build if present
const CLIENT_DIST = path.resolve(__dirname, '../../client/dist');
if (fs.existsSync(CLIENT_DIST)) {
