export function formatRelativeTime(dateString: string): string {
  if (!dateString) return '';
  const date = new Date(dateString);
  const now = new Date();
  const diffInSeconds = Math.floor((now.getTime() - date.getTime()) / 1000);

  if (diffInSeconds < 5) return 'just now';
  if (diffInSeconds < 60) return `${diffInSeconds}s ago`;

  const diffInMinutes = Math.floor(diffInSeconds / 60);
  if (diffInMinutes < 60) return `${diffInMinutes}m ago`;

  const diffInHours = Math.floor(diffInMinutes / 60);
  if (diffInHours < 24) return `${diffInHours}h ago`;

  const diffInDays = Math.floor(diffInHours / 24);
  return `${diffInDays}d ago`;
}

export function formatDateTime(dateString: string): string {
  if (!dateString) return '';
  const date = new Date(dateString);
  return date.toLocaleString('en-US', {
    month: 'short',
    day: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
  });
}

export function getStateBadgeConfig(state: TaskState) {
  switch (state) {
    case 'routing':
      return {
        label: 'Routing',
        bg: 'bg-amber-500/15 text-amber-300 border-amber-500/30',
        dot: 'bg-amber-400 animate-pulse',
        glow: 'shadow-amber-500/20 shadow-sm',
      };
    case 'assigned':
      return {
        label: 'Assigned',
        bg: 'bg-indigo-500/15 text-indigo-300 border-indigo-500/30',
        dot: 'bg-indigo-400',
        glow: 'shadow-indigo-500/20 shadow-sm',
      };
    case 'accepted':
      return {
        label: 'Accepted',
        bg: 'bg-emerald-500/15 text-emerald-300 border-emerald-500/30',
        dot: 'bg-emerald-400',
        glow: 'shadow-emerald-500/20 shadow-sm',
      };
    case 'declined':
      return {
        label: 'Declined',
        bg: 'bg-rose-500/15 text-rose-300 border-rose-500/30',
        dot: 'bg-rose-400',
        glow: 'shadow-rose-500/20 shadow-sm',
      };
    case 'failed':
      return {
        label: 'Failed (No Match)',
        bg: 'bg-red-500/15 text-red-300 border-red-500/30',
        dot: 'bg-red-400',
        glow: 'shadow-red-500/20 shadow-sm',
      };
    case 'recovered':
      return {
        label: 'Recovered',
        bg: 'bg-sky-500/15 text-sky-300 border-sky-500/30',
        dot: 'bg-sky-400',
        glow: 'shadow-sky-500/20 shadow-sm',
      };
    case 'cancelled':
      return {
        label: 'Cancelled',
        bg: 'bg-slate-700/40 text-slate-400 border-slate-600/40',
        dot: 'bg-slate-500',
        glow: '',
      };
    case 'pending':
    default:
      return {
        label: 'Pending',
        bg: 'bg-slate-800 text-slate-300 border-slate-700',
        dot: 'bg-slate-400',
        glow: '',
      };
  }
}

export function getActorConfig(actor: ActorType) {
  switch (actor) {
    case 'routing_engine':
      return {
        name: 'Routing Engine',
        badge: 'bg-purple-500/20 text-purple-300 border-purple-500/30',
        icon: 'Bot',
      };
    case 'operator':
      return {
        name: 'Human Operator',
        badge: 'bg-blue-500/20 text-blue-300 border-blue-500/30',
        icon: 'UserCheck',
      };
    case 'contributor':
      return {
        name: 'Contributor',
        badge: 'bg-emerald-500/20 text-emerald-300 border-emerald-500/30',
        icon: 'User',
      };
    default:
      return {
        name: 'System',
        badge: 'bg-slate-700/50 text-slate-300 border-slate-600',
        icon: 'Cpu',
      };
  }
}

