            ? 'bg-amber-950/30 border-amber-500/50 shadow-md shadow-amber-500/10'
            : 'bg-slate-900/60 border-slate-800/80 hover:bg-slate-800/40'
        }`}
      >
        <div className="flex items-center justify-between text-amber-400 text-xs mb-1 font-medium">
          <span>In Routing</span>
          <Loader2 className={`h-3.5 w-3.5 text-amber-400 ${stats.routing > 0 ? 'animate-spin' : ''}`} />
        </div>
        <div className="text-2xl font-bold text-amber-300 tracking-tight flex items-baseline space-x-2">
          <span>{stats.routing}</span>
          {stats.stuckRouting > 0 && (
            <span className="text-xs px-1.5 py-0.5 rounded bg-rose-500/20 text-rose-300 font-semibold border border-rose-500/30">
              {stats.stuckRouting} stuck
            </span>
          )}
        </div>
        <div className="text-[11px] text-slate-500 mt-0.5">5-20s matching window</div>
      </div>

      {/* 3. Assigned */}
      <div
        onClick={() => onSelectFilter('assigned')}
        className={`p-3.5 rounded-xl border transition cursor-pointer ${
          activeFilter === 'assigned'
            ? 'bg-indigo-950/30 border-indigo-500/50 shadow-md shadow-indigo-500/10'
            : 'bg-slate-900/60 border-slate-800/80 hover:bg-slate-800/40'
        }`}
      >
        <div className="flex items-center justify-between text-indigo-400 text-xs mb-1 font-medium">
          <span>Assigned</span>
          <UserCheck className="h-3.5 w-3.5 text-indigo-400" />
        </div>
        <div className="text-2xl font-bold text-indigo-300 tracking-tight">{stats.assigned}</div>
        <div className="text-[11px] text-slate-500 mt-0.5">Awaiting completion</div>
      </div>

      {/* 4. Accepted */}
      <div
        onClick={() => onSelectFilter('accepted')}
        className={`p-3.5 rounded-xl border transition cursor-pointer ${
          activeFilter === 'accepted'
            ? 'bg-emerald-950/30 border-emerald-500/50 shadow-md shadow-emerald-500/10'
            : 'bg-slate-900/60 border-slate-800/80 hover:bg-slate-800/40'
        }`}
      >
        <div className="flex items-center justify-between text-emerald-400 text-xs mb-1 font-medium">
          <span>Accepted</span>
          <CheckCircle2 className="h-3.5 w-3.5 text-emerald-400" />
        </div>
        <div className="text-2xl font-bold text-emerald-300 tracking-tight">{stats.accepted}</div>
        <div className="text-[11px] text-slate-500 mt-0.5">Routing finished</div>
      </div>

      {/* 5. Needs Recovery */}
      <div
        onClick={() => onSelectFilter('needs_recovery')}
        className={`p-3.5 rounded-xl border transition cursor-pointer ${
          activeFilter === 'needs_recovery'
            ? 'bg-rose-950/30 border-rose-500/50 shadow-md shadow-rose-500/10'
            : 'bg-slate-900/60 border-slate-800/80 hover:bg-slate-800/40'
        }`}
      >
        <div className="flex items-center justify-between text-rose-400 text-xs mb-1 font-medium">
          <span>Needs Recovery</span>
          <AlertCircle className="h-3.5 w-3.5 text-rose-400" />
        </div>
        <div className="text-2xl font-bold text-rose-300 tracking-tight">
          {needsRecoveryCount}
        </div>
        <div className="text-[11px] text-slate-500 mt-0.5">
          {stats.failed} failed • {stats.declined} declined
        </div>
      </div>

      {/* 6. Contributors */}
      <div className="p-3.5 rounded-xl border bg-slate-900/60 border-slate-800/80">
        <div className="flex items-center justify-between text-sky-400 text-xs mb-1 font-medium">
          <span>Contributors</span>
          <Users className="h-3.5 w-3.5 text-sky-400" />
        </div>
        <div className="text-2xl font-bold text-sky-300 tracking-tight">
          {stats.totalContributors}
        </div>
        <div className="text-[11px] text-slate-500 mt-0.5">
          {stats.availableContributors} ready for routing
        </div>
      </div>
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { Task, Contributor } from '../types.js';
import {
  getStateBadgeConfig,
  formatRelativeTime,
  formatDateTime,
} from '../utils.js';
import {
  Clock,
  User,
  Zap,
  RotateCw,
  Check,
  X,
  History,
  AlertTriangle,
  Loader2,
  Tag,
  ShieldAlert,
} from 'lucide-react';

interface TaskCardProps {
  task: Task;
  onInspectHistory: (task: Task) => void;
  onIntervene: (task: Task) => void;
  onRecover: (task: Task) => void;
  onContributorAccept: (taskId: string) => void;
  onContributorDecline: (taskId: string) => void;
}

export const TaskCard: React.FC<TaskCardProps> = ({
  task,
  onInspectHistory,
  onIntervene,
  onRecover,
  onContributorAccept,
  onContributorDecline,
}) => {
  const badge = getStateBadgeConfig(task.state);
  const [elapsedSec, setElapsedSec] = useState<number>(0);

  // Live timer for tasks currently in routing
  useEffect(() => {
    if (task.state !== 'routing' || !task.routingStartedAt) {
      setElapsedSec(0);
      return;
    }

    const calcElapsed = () => {
      const start = new Date(task.routingStartedAt!).getTime();
      const now = Date.now();
      return Math.max(0, Math.floor((now - start) / 1000));
    };

    setElapsedSec(calcElapsed());
    const interval = setInterval(() => {
      setElapsedSec(calcElapsed());
    }, 1000);

    return () => clearInterval(interval);
  }, [task.state, task.routingStartedAt]);

  const isStuckWarning =
    task.state === 'routing' && (task.isStuckSimulated || elapsedSec > 20);

  return (
    <div
      className={`rounded-xl border bg-slate-900/80 p-5 transition-all flex flex-col justify-between hover:border-slate-700 shadow-lg ${
        isStuckWarning
          ? 'border-amber-500/50 ring-1 ring-amber-500/30'
          : 'border-slate-800'
      }`}
    >
      <div>
        {/* Top Header: ID, Time & Status Badge */}
        <div className="flex items-start justify-between gap-2 mb-3">
          <div className="flex items-center space-x-2">
            <span className="font-mono text-xs font-bold px-2 py-0.5 rounded bg-slate-800 text-slate-300 border border-slate-700">
              {task.id}
            </span>
            <span
              className="text-xs text-slate-400 flex items-center space-x-1"
              title={`Created: ${formatDateTime(task.createdAt)}`}
            >
              <Clock className="h-3 w-3" />
              <span>{formatRelativeTime(task.createdAt)}</span>
            </span>
          </div>

          {/* State Badge */}
          <span
            className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-semibold border ${badge.bg} ${badge.glow}`}
          >
            <span className={`h-1.5 w-1.5 rounded-full mr-1.5 ${badge.dot}`} />
            {badge.label}
          </span>
        </div>

        {/* Title & Description */}
        <h3 className="font-bold text-slate-100 text-base leading-snug mb-1 line-clamp-1">
          {task.title}
        </h3>
        <p className="text-xs text-slate-400 line-clamp-2 mb-4 leading-relaxed">
          {task.description || 'No description provided.'}
        </p>

        {/* Required Expertise Pill */}
        <div className="flex items-center space-x-2 mb-4">
          <span className="text-[11px] text-slate-400 uppercase tracking-wider font-semibold">
            Expertise:
          </span>
          <span className="inline-flex items-center space-x-1 px-2.5 py-1 rounded-md text-xs font-medium bg-indigo-950/50 text-indigo-300 border border-indigo-800/50">
            <Tag className="h-3 w-3 text-indigo-400" />
            <span>{task.expertiseRequired}</span>
          </span>
          {task.routingAttempt > 1 && (
            <span className="text-[11px] px-1.5 py-0.5 rounded bg-slate-800 text-slate-400 border border-slate-700">
              Attempt #{task.routingAttempt}
            </span>
          )}
        </div>

        {/* Routing In-Progress Banner */}
        {task.state === 'routing' && (
          <div
            className={`rounded-lg p-3 mb-4 border ${
              isStuckWarning
                ? 'bg-amber-950/30 border-amber-500/40 text-amber-200'
                : 'bg-indigo-950/20 border-indigo-500/30 text-indigo-200'
            }`}
          >
            <div className="flex items-center justify-between text-xs font-medium mb-1.5">
              <span className="flex items-center space-x-1.5">
                <Loader2 className="h-3.5 w-3.5 animate-spin" />
                <span>
                  {task.isStuckSimulated
                    ? 'Background Worker Hanging'
                    : 'Matching Eligible Contributors...'}
                </span>
              </span>
              <span className="font-mono font-bold text-xs px-2 py-0.5 rounded bg-black/40">
                {elapsedSec}s elapsed
              </span>
            </div>

            {isStuckWarning && (
              <div className="mt-2 text-[11px] leading-tight text-amber-300/90 flex items-start space-x-1.5">
                <AlertTriangle className="h-3.5 w-3.5 text-amber-400 shrink-0 mt-0.5" />
                <span>
                  <strong>20% Edge Case Detected:</strong> Request has not returned in normal window.
                  Operator intervention required to cancel, manual assign, or re-route.
                </span>
              </div>
            )}
          </div>
        )}

        {/* Active Assignee Banner */}
        {task.activeAssignee && (
          <div className="rounded-lg p-2.5 bg-slate-950/60 border border-slate-800 mb-4 flex items-center justify-between">
            <div className="flex items-center space-x-3">
              <img
                src={task.activeAssignee.avatar}
                alt={task.activeAssignee.name}
                className="h-8 w-8 rounded-full object-cover border border-slate-700"
              />
              <div>
                <div className="text-xs font-bold text-slate-200 flex items-center space-x-1.5">
                  <span>{task.activeAssignee.name}</span>
                  <span className="text-[10px] text-emerald-400 font-normal">
                    (Active Assignee)
                  </span>
                </div>
                <div className="text-[11px] text-slate-400">
                  {task.activeAssignee.title}
                </div>
              </div>
            </div>
            {task.assignedAt && (
              <span className="text-[10px] text-slate-500 font-mono">
                {formatRelativeTime(task.assignedAt)}
              </span>
            )}
          </div>
        )}

        {/* Declined / Failed Banner */}
        {(task.state === 'declined' || task.state === 'failed') && (
          <div className="rounded-lg p-2.5 bg-rose-950/20 border border-rose-500/30 text-rose-200 text-xs mb-4">
            <div className="flex items-center space-x-1.5 font-semibold text-rose-300 mb-0.5">
              <ShieldAlert className="h-3.5 w-3.5" />
              <span>
                {task.state === 'declined'
                  ? 'Contributor Declined Assignment'
                  : 'No Matching Contributor Found'}
              </span>
            </div>
            <p className="text-[11px] text-rose-300/80">
              {task.state === 'declined'
                ? 'Task was rejected by assignee. Operator recovery needed to re-route or manually assign.'
                : `No registered contributors have expertise in '${task.expertiseRequired}'. Requires recovery.`}
            </p>
          </div>
        )}

        {/* Accepted Banner */}
        {task.state === 'accepted' && (
          <div className="rounded-lg p-2 bg-emerald-950/20 border border-emerald-500/30 text-emerald-300 text-xs mb-4 flex items-center space-x-2">
            <Check className="h-4 w-4 text-emerald-400 shrink-0" />
            <span className="text-[11px]">
              Assignment accepted. Routing for this task is finished.
            </span>
          </div>
        )}
      </div>

      {/* Action Footer */}
      <div className="pt-3 border-t border-slate-800/80 flex flex-wrap items-center justify-between gap-2">
        {/* Left side actions based on state */}
        <div className="flex items-center space-x-1.5">
          {/* While Routing: Intervene */}
          {task.state === 'routing' && (
            <button
              onClick={() => onIntervene(task)}
              className="flex items-center space-x-1 px-3 py-1.5 rounded-lg text-xs font-semibold bg-amber-500/20 text-amber-200 border border-amber-500/40 hover:bg-amber-500/30 transition cursor-pointer"
            >
              <Zap className="h-3.5 w-3.5 text-amber-400" />
              <span>Intervene</span>
            </button>
          )}

          {/* When Assigned: Contributor Accept / Decline Simulation */}
          {task.state === 'assigned' && (
            <div className="flex items-center space-x-1">
              <button
                onClick={() => onContributorAccept(task.id)}
                title="Simulate contributor accepting assignment (finishes routing)"
                className="flex items-center space-x-1 px-2.5 py-1.5 rounded-lg text-xs font-semibold bg-emerald-500/20 text-emerald-300 border border-emerald-500/40 hover:bg-emerald-500/30 transition cursor-pointer"
              >
                <Check className="h-3 w-3" />
                <span>Accept</span>
              </button>
              <button
                onClick={() => onContributorDecline(task.id)}
                title="Simulate contributor declining assignment"
                className="flex items-center space-x-1 px-2.5 py-1.5 rounded-lg text-xs font-semibold bg-rose-500/20 text-rose-300 border border-rose-500/40 hover:bg-rose-500/30 transition cursor-pointer"
              >
                <X className="h-3 w-3" />
                <span>Decline</span>
              </button>
              <button
                onClick={() => onIntervene(task)}
                title="Operator Reassign"
                className="p-1.5 rounded-lg text-slate-400 hover:text-slate-200 hover:bg-slate-800 transition cursor-pointer"
              >
                <User className="h-3.5 w-3.5" />
              </button>
            </div>
          )}

          {/* When Failed / Declined: Recover */}
          {(task.state === 'failed' ||
            task.state === 'declined' ||
            task.state === 'cancelled') && (
            <button
              onClick={() => onRecover(task)}
              className="flex items-center space-x-1 px-3 py-1.5 rounded-lg text-xs font-semibold bg-sky-500/20 text-sky-200 border border-sky-500/40 hover:bg-sky-500/30 transition cursor-pointer"
            >
              <RotateCw className="h-3.5 w-3.5 text-sky-400" />
              <span>Recover Task</span>
            </button>
          )}
        </div>

        {/* View Timeline / Audit Log */}
        <button
          onClick={() => onInspectHistory(task)}
          className="flex items-center space-x-1 px-2.5 py-1.5 rounded-lg text-xs font-medium text-slate-300 hover:text-white bg-slate-800/80 hover:bg-slate-800 border border-slate-700 transition cursor-pointer ml-auto"
        >
          <History className="h-3.5 w-3.5 text-slate-400" />
          <span>Timeline ({task.history ? task.history.length : 0})</span>
        </button>
      </div>
    </div>
  );
};

import React from 'react';
import { Task, TaskHistoryEntry } from '../types.js';
import {
  getStateBadgeConfig,
  getActorConfig,
  formatDateTime,
  formatRelativeTime,
} from '../utils.js';
import {
  X,
  Bot,
  UserCheck,
  User,
  Cpu,
  ArrowRight,
  Clock,
  Tag,
  ShieldCheck,
  AlertTriangle,
} from 'lucide-react';

interface TaskHistoryModalProps {
  task: Task | null;
  onClose: () => void;
  onIntervene?: (task: Task) => void;
  onRecover?: (task: Task) => void;
}

export const TaskHistoryModal: React.FC<TaskHistoryModalProps> = ({
  task,
  onClose,
  onIntervene,
  onRecover,
}) => {
  if (!task) return null;

  const currentBadge = getStateBadgeConfig(task.state);

  const renderActorIcon = (actor: string) => {
    switch (actor) {
      case 'routing_engine':
        return <Bot className="h-4 w-4 text-purple-400" />;
      case 'operator':
        return <UserCheck className="h-4 w-4 text-blue-400" />;
      case 'contributor':
        return <User className="h-4 w-4 text-emerald-400" />;
      default:
        return <Cpu className="h-4 w-4 text-slate-400" />;
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/75 backdrop-blur-sm animate-in fade-in duration-200">
      <div className="bg-slate-900 border border-slate-800 rounded-2xl w-full max-w-3xl max-h-[90vh] flex flex-col shadow-2xl overflow-hidden">
        {/* Header */}
        <div className="p-5 border-b border-slate-800 flex items-start justify-between bg-slate-950/60">
          <div>
            <div className="flex items-center space-x-2.5 mb-1.5">
              <span className="font-mono text-xs font-bold px-2 py-0.5 rounded bg-slate-800 text-slate-300 border border-slate-700">
                {task.id}
              </span>
              <span
                className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-semibold border ${currentBadge.bg}`}
              >
                <span className={`h-1.5 w-1.5 rounded-full mr-1.5 ${currentBadge.dot}`} />
                {currentBadge.label}
              </span>
              <span className="inline-flex items-center space-x-1 px-2 py-0.5 rounded text-xs bg-indigo-950/40 text-indigo-300 border border-indigo-800/40">
                <Tag className="h-3 w-3" />
                <span>{task.expertiseRequired}</span>
              </span>
            </div>
            <h2 className="text-lg font-bold text-white">{task.title}</h2>
            <p className="text-xs text-slate-400 mt-1">
              Created {formatDateTime(task.createdAt)} ({formatRelativeTime(task.createdAt)})
            </p>
          </div>

          <button
            onClick={onClose}
            className="p-1.5 rounded-lg text-slate-400 hover:text-white hover:bg-slate-800 transition cursor-pointer"
          >
            <X className="h-5 w-5" />
          </button>
        </div>

        {/* Content Body: Task Context & Timeline */}
        <div className="p-6 overflow-y-auto space-y-6 flex-1">
          {/* Active Assignee summary if assigned */}
          {task.activeAssignee && (
            <div className="p-4 rounded-xl bg-slate-950/60 border border-slate-800 flex items-center justify-between">
              <div className="flex items-center space-x-3">
                <img
                  src={task.activeAssignee.avatar}
                  alt={task.activeAssignee.name}
                  className="h-10 w-10 rounded-full object-cover border border-slate-700"
                />
                <div>
                  <div className="text-xs font-bold text-white flex items-center space-x-2">
                    <span>{task.activeAssignee.name}</span>
                    <span className="text-[10px] px-1.5 py-0.5 rounded bg-emerald-500/20 text-emerald-300 border border-emerald-500/30">
                      Active Assignee (Max 1 per task)
                    </span>
                  </div>
                  <div className="text-xs text-slate-400">{task.activeAssignee.email}</div>
                  <div className="flex items-center space-x-1 mt-1">
                    {task.activeAssignee.expertise.map((exp) => (
                      <span
                        key={exp}
                        className={`text-[10px] px-1.5 py-0.2 rounded ${
                          exp.toLowerCase() === task.expertiseRequired.toLowerCase()
                            ? 'bg-indigo-500/20 text-indigo-300 font-semibold border border-indigo-500/30'
                            : 'bg-slate-800 text-slate-400'
                        }`}
                      >
                        {exp}
                      </span>
                    ))}
                  </div>
                </div>
              </div>

              {task.assignedAt && (
                <div className="text-right text-xs text-slate-400">
                  <div className="text-[11px] uppercase tracking-wider text-slate-500 font-semibold">
                    Assigned At
                  </div>
                  <div>{formatDateTime(task.assignedAt)}</div>
                </div>
              )}
            </div>
          )}

          {/* Audit Log / Timeline Section */}
          <div>
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-sm font-bold text-slate-200 uppercase tracking-wider flex items-center space-x-2">
                <ShieldCheck className="h-4 w-4 text-indigo-400" />
                <span>Complete Audit Log & State History</span>
              </h3>
              <span className="text-xs text-slate-500 font-mono">
                {task.history ? task.history.length : 0} event(s) recorded
              </span>
            </div>

            {/* Timeline Tree */}
            <div className="relative pl-6 space-y-6 before:absolute before:left-3 before:top-2 before:bottom-2 before:w-0.5 before:bg-slate-800">
              {task.history && task.history.length > 0 ? (
                task.history.map((entry, index) => {
                  const actorConfig = getActorConfig(entry.actor);
                  const isLatest = index === task.history.length - 1;

                  return (
                    <div key={entry.id || index} className="relative group">
                      {/* Timeline Dot */}
                      <div
                        className={`absolute -left-6 top-1.5 h-6 w-6 rounded-full border flex items-center justify-center bg-slate-900 ${
                          isLatest
                            ? 'border-indigo-500 shadow-md shadow-indigo-500/30'
                            : 'border-slate-700'
                        }`}
                      >
                        {renderActorIcon(entry.actor)}
                      </div>

                      {/* Event Card */}
                      <div className="bg-slate-950/70 border border-slate-800/90 rounded-xl p-4 hover:border-slate-700 transition">
                        {/* Header: Actor, Action, State transition */}
                        <div className="flex flex-wrap items-center justify-between gap-2 mb-2">
                          <div className="flex items-center space-x-2">
                            <span
                              className={`text-[11px] font-bold px-2 py-0.5 rounded border ${actorConfig.badge}`}
                            >
                              {entry.actorName || actorConfig.name}
                            </span>
                            <span className="text-xs font-mono font-semibold text-slate-300">
                              {entry.action}
                            </span>
                          </div>

                          {/* State Transition Badge */}
                          <div className="flex items-center space-x-1.5 text-xs font-mono">
                            {entry.previousState && (
                              <>
                                <span className="text-slate-500">{entry.previousState}</span>
                                <ArrowRight className="h-3 w-3 text-slate-600" />
                              </>
                            )}
                            <span className="font-bold text-indigo-400 px-1.5 py-0.5 rounded bg-indigo-500/10 border border-indigo-500/20">
                              {entry.newState}
                            </span>
                          </div>
                        </div>

                        {/* Event Narrative Details */}
                        <p className="text-xs text-slate-300 leading-relaxed">
                          {entry.details}
                        </p>

                        {/* Metadata tags if present */}
                        {entry.metadata && Object.keys(entry.metadata).length > 0 && (
                          <div className="mt-2.5 pt-2 border-t border-slate-900 flex flex-wrap gap-2 text-[11px] font-mono text-slate-400">
                            {Object.entries(entry.metadata).map(([k, v]) => (
                              <span
                                key={k}
                                className="px-1.5 py-0.5 rounded bg-slate-900 text-slate-400 border border-slate-800"
                              >
                                {k}: {typeof v === 'boolean' ? (v ? 'true' : 'false') : String(v)}
                              </span>
                            ))}
                          </div>
                        )}

                        {/* Timestamp */}
                        <div className="mt-2 text-[10px] text-slate-500 flex items-center space-x-1">
                          <Clock className="h-3 w-3" />
                          <span>{formatDateTime(entry.timestamp)}</span>
                          <span>•</span>
                          <span>{formatRelativeTime(entry.timestamp)}</span>
                        </div>
                      </div>
                    </div>
                  );
                })
              ) : (
                <div className="text-xs text-slate-500 italic">No history records found.</div>
              )}
            </div>
          </div>
        </div>

        {/* Footer */}
        <div className="p-4 border-t border-slate-800 bg-slate-950/80 flex items-center justify-between">
          <div className="text-xs text-slate-500">
            Audit logs are immutable and sequentially tracked.
          </div>
          <button
            onClick={onClose}
            className="px-4 py-2 rounded-lg text-xs font-semibold bg-slate-800 hover:bg-slate-700 text-slate-200 transition cursor-pointer"
          >
            Close Inspector
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { X, Sparkles, AlertTriangle, Send } from 'lucide-react';

interface NewTaskModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSubmit: (data: {
    title: string;
    description: string;
    expertiseRequired: string;
    autoRoute: boolean;
    forceStuck: boolean;
  }) => Promise<void>;
}

const PRESET_EXPERTISE = [
  'Finance',
  'Healthcare',
  'Data Analysis',
  'Operations',
  'Legal',
  'Security',
];

export const NewTaskModal: React.FC<NewTaskModalProps> = ({
  isOpen,
  onClose,
  onSubmit,
}) => {
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [expertiseRequired, setExpertiseRequired] = useState('Finance');
  const [customExpertise, setCustomExpertise] = useState('');
  const [isCustom, setIsCustom] = useState(false);
  const [autoRoute, setAutoRoute] = useState(true);
  const [forceStuck, setForceStuck] = useState(false);
  const [submitting, setSubmitting] = useState(false);

  if (!isOpen) return null;

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const finalExpertise = isCustom ? customExpertise.trim() : expertiseRequired;
    if (!title.trim() || !finalExpertise) return;

    try {
      setSubmitting(true);
      await onSubmit({
        title: title.trim(),
        description: description.trim(),
        expertiseRequired: finalExpertise,
        autoRoute,
        forceStuck,
      });
      // reset form
      setTitle('');
      setDescription('');
      setExpertiseRequired('Finance');
      setCustomExpertise('');
      setIsCustom(false);
      setForceStuck(false);
      onClose();
    } catch (err) {
      console.error(err);
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/75 backdrop-blur-sm animate-in fade-in duration-200">
      <div className="bg-slate-900 border border-slate-800 rounded-2xl w-full max-w-lg shadow-2xl overflow-hidden flex flex-col">
        {/* Header */}
        <div className="p-5 border-b border-slate-800 flex items-center justify-between bg-slate-950/60">
          <div className="flex items-center space-x-2.5">
            <div className="h-8 w-8 rounded-lg bg-indigo-500/20 text-indigo-400 flex items-center justify-center border border-indigo-500/30">
              <Sparkles className="h-4 w-4" />
            </div>
            <div>
              <h2 className="text-base font-bold text-white">Create New Task</h2>
              <p className="text-xs text-slate-400">
                Define task requirements and dispatch to routing engine
              </p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="p-1.5 rounded-lg text-slate-400 hover:text-white hover:bg-slate-800 transition cursor-pointer"
          >
            <X className="h-4 w-4" />
          </button>
        </div>

        {/* Form Body */}
        <form onSubmit={handleSubmit} className="p-6 space-y-4">
          {/* Title */}
          <div>
            <label className="block text-xs font-semibold text-slate-300 uppercase tracking-wider mb-1.5">
              Task Title *
            </label>
            <input
              type="text"
              required
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              placeholder="e.g. Q4 Hospital Revenue Cycle Audit"
              className="w-full px-3.5 py-2.5 rounded-xl bg-slate-950 border border-slate-800 focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500 text-sm text-slate-100 placeholder-slate-500 outline-none transition"
            />
          </div>

          {/* Description */}
          <div>
            <label className="block text-xs font-semibold text-slate-300 uppercase tracking-wider mb-1.5">
              Description
            </label>
            <textarea
              rows={3}
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              placeholder="Detail specific deliverables, constraints, or context..."
              className="w-full px-3.5 py-2.5 rounded-xl bg-slate-950 border border-slate-800 focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500 text-sm text-slate-100 placeholder-slate-500 outline-none transition resize-none"
            />
          </div>

          {/* Required Expertise Area */}
          <div>
            <label className="block text-xs font-semibold text-slate-300 uppercase tracking-wider mb-1.5">
              Required Expertise Area *
            </label>
            <div className="grid grid-cols-3 gap-2 mb-2">
              {PRESET_EXPERTISE.map((exp) => {
                const selected = !isCustom && expertiseRequired === exp;
                return (
                  <button
                    key={exp}
                    type="button"
                    onClick={() => {
                      setIsCustom(false);
                      setExpertiseRequired(exp);
                    }}
                    className={`px-3 py-2 rounded-lg text-xs font-semibold border transition text-left cursor-pointer ${
                      selected
                        ? 'bg-indigo-600/20 border-indigo-500 text-indigo-300'
                        : 'bg-slate-950/80 border-slate-800 text-slate-400 hover:text-slate-200 hover:border-slate-700'
                    }`}
                  >
                    {exp}
                  </button>
                );
              })}
            </div>

            {/* Custom Expertise option */}
            <div className="flex items-center space-x-2 mt-2">
              <input
                type="text"
                placeholder="Or specify custom expertise (e.g. Quantum Computing)..."
                value={customExpertise}
                onFocus={() => setIsCustom(true)}
                onChange={(e) => {
                  setIsCustom(true);
                  setCustomExpertise(e.target.value);
                }}
                className={`flex-1 px-3 py-2 rounded-lg text-xs bg-slate-950 border outline-none transition ${
                  isCustom
                    ? 'border-indigo-500 text-indigo-200'
                    : 'border-slate-800 text-slate-400 focus:border-slate-700'
                }`}
              />
            </div>
            <p className="text-[11px] text-slate-500 mt-1">
              If no registered contributor matches this expertise, the engine will report "No match found".
            </p>
          </div>

          {/* Routing Options */}
          <div className="pt-2 border-t border-slate-800/80 space-y-2.5">
            <label className="flex items-center space-x-2.5 cursor-pointer">
              <input
                type="checkbox"
                checked={autoRoute}
                onChange={(e) => setAutoRoute(e.target.checked)}
                className="h-4 w-4 rounded border-slate-700 bg-slate-950 text-indigo-600 focus:ring-indigo-500"
              />
              <span className="text-xs text-slate-300">
                Immediately submit to background routing engine (5–20s matching window)
              </span>
            </label>

            {/* Force Stuck Testing Option */}
            {autoRoute && (
              <label className="flex items-start space-x-2.5 p-2.5 rounded-lg bg-amber-950/20 border border-amber-500/30 cursor-pointer">
                <input
                  type="checkbox"
                  checked={forceStuck}
                  onChange={(e) => setForceStuck(e.target.checked)}
                  className="h-4 w-4 mt-0.5 rounded border-amber-600 bg-slate-950 text-amber-500 focus:ring-amber-500"
                />
                <div>
                  <span className="text-xs font-bold text-amber-300 flex items-center space-x-1">
                    <AlertTriangle className="h-3 w-3 inline text-amber-400" />
                    <span>Explicitly Simulate 20% Hanging Edge Case</span>
                  </span>
                  <span className="text-[11px] text-amber-400/80 block leading-tight mt-0.5">
                    Forces the background request to stay stuck indefinitely without returning, allowing immediate testing of operator intervention.
                  </span>
                </div>
              </label>
            )}
          </div>

          {/* Actions */}
          <div className="pt-3 flex items-center justify-end space-x-2.5">
            <button
              type="button"
              onClick={onClose}
              className="px-4 py-2 rounded-xl text-xs font-semibold text-slate-400 hover:text-white hover:bg-slate-800 transition cursor-pointer"
            >
              Cancel
            </button>
            <button
              type="submit"
              disabled={submitting || !title.trim()}
              className="flex items-center space-x-1.5 px-5 py-2.5 rounded-xl text-xs font-bold bg-indigo-600 hover:bg-indigo-500 text-white shadow-lg shadow-indigo-600/30 disabled:opacity-50 transition cursor-pointer"
            >
              <Send className="h-3.5 w-3.5" />
              <span>{submitting ? 'Creating...' : autoRoute ? 'Create & Route' : 'Create Draft'}</span>
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Task, Contributor } from '../types.js';
import {
  X,
  Zap,
  UserCheck,
  Ban,
  RotateCw,
  AlertCircle,
  Tag,
  Check,
} from 'lucide-react';

interface InterveneModalProps {
  task: Task | null;
  contributors: Contributor[];
  isOpen: boolean;
  onClose: () => void;
  onExecute: (
    action: 'manual_assign' | 'cancel_routing' | 'force_reroute',
    contributorId?: string,
    reason?: string
  ) => Promise<void>;
}

export const InterveneModal: React.FC<InterveneModalProps> = ({
  task,
  contributors,
  isOpen,
  onClose,
  onExecute,
}) => {
  const [selectedAction, setSelectedAction] = useState<
    'manual_assign' | 'cancel_routing' | 'force_reroute'
  >('manual_assign');
  const [selectedContributorId, setSelectedContributorId] = useState<string>('');
  const [reason, setReason] = useState<string>('');
  const [submitting, setSubmitting] = useState<boolean>(false);

  if (!isOpen || !task) return null;

  // Find matching contributors for guidance
  const matchingContributors = contributors.filter((c) =>
    c.expertise.map((e) => e.toLowerCase()).includes(task.expertiseRequired.toLowerCase())
  );
  const otherContributors = contributors.filter(
    (c) =>
      !c.expertise.map((e) => e.toLowerCase()).includes(task.expertiseRequired.toLowerCase())
  );

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (selectedAction === 'manual_assign' && !selectedContributorId) return;

    try {
      setSubmitting(true);
      await onExecute(selectedAction, selectedContributorId, reason.trim());
      setReason('');
      setSelectedContributorId('');
      onClose();
    } catch (err) {
      console.error(err);
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/75 backdrop-blur-sm animate-in fade-in duration-200">
      <div className="bg-slate-900 border border-slate-800 rounded-2xl w-full max-w-xl shadow-2xl overflow-hidden flex flex-col max-h-[90vh]">
        {/* Header */}
        <div className="p-5 border-b border-slate-800 flex items-center justify-between bg-slate-950/60">
          <div className="flex items-center space-x-2.5">
            <div className="h-8 w-8 rounded-lg bg-amber-500/20 text-amber-400 flex items-center justify-center border border-amber-500/30">
              <Zap className="h-4 w-4" />
            </div>
            <div>
              <div className="flex items-center space-x-2">
                <h2 className="text-base font-bold text-white">Operator Intervention</h2>
                <span className="font-mono text-xs text-slate-400 bg-slate-800 px-2 py-0.5 rounded border border-slate-700">
                  {task.id}
                </span>
              </div>
              <p className="text-xs text-slate-400">
                Override background routing or modify assignment directly
              </p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="p-1.5 rounded-lg text-slate-400 hover:text-white hover:bg-slate-800 transition cursor-pointer"
          >
            <X className="h-4 w-4" />
          </button>
        </div>

        {/* Task Summary Banner */}
        <div className="px-6 py-3 bg-slate-950/40 border-b border-slate-800/80 flex items-center justify-between text-xs">
          <div>
            <span className="text-slate-400">Task: </span>
            <span className="font-semibold text-slate-200">{task.title}</span>
          </div>
          <div className="flex items-center space-x-1.5">
            <span className="text-slate-400">Required: </span>
            <span className="font-medium text-indigo-300 px-2 py-0.5 rounded bg-indigo-950/40 border border-indigo-800/40">
              {task.expertiseRequired}
            </span>
          </div>
        </div>

        {/* Form Body */}
        <form onSubmit={handleSubmit} className="p-6 overflow-y-auto space-y-5 flex-1">
          {/* Action Choice Tabs */}
          <div>
            <label className="block text-xs font-semibold text-slate-300 uppercase tracking-wider mb-2">
              Select Intervention Action
            </label>
            <div className="grid grid-cols-3 gap-2">
              <button
                type="button"
                onClick={() => setSelectedAction('manual_assign')}
                className={`p-3 rounded-xl border text-left transition cursor-pointer ${
                  selectedAction === 'manual_assign'
                    ? 'bg-indigo-600/20 border-indigo-500 text-indigo-200'
                    : 'bg-slate-950/60 border-slate-800 text-slate-400 hover:text-slate-200'
                }`}
              >
                <UserCheck className="h-4 w-4 mb-1 text-indigo-400" />
                <div className="text-xs font-bold">Manual Assign</div>
                <div className="text-[10px] text-slate-400 mt-0.5">Pick contributor directly</div>
              </button>

              <button
                type="button"
                onClick={() => setSelectedAction('cancel_routing')}
                className={`p-3 rounded-xl border text-left transition cursor-pointer ${
                  selectedAction === 'cancel_routing'
                    ? 'bg-rose-600/20 border-rose-500 text-rose-200'
                    : 'bg-slate-950/60 border-slate-800 text-slate-400 hover:text-slate-200'
                }`}
              >
                <Ban className="h-4 w-4 mb-1 text-rose-400" />
                <div className="text-xs font-bold">Cancel Routing</div>
                <div className="text-[10px] text-slate-400 mt-0.5">Abort background job</div>
              </button>

              <button
                type="button"
                onClick={() => setSelectedAction('force_reroute')}
                className={`p-3 rounded-xl border text-left transition cursor-pointer ${
                  selectedAction === 'force_reroute'
                    ? 'bg-amber-600/20 border-amber-500 text-amber-200'
                    : 'bg-slate-950/60 border-slate-800 text-slate-400 hover:text-slate-200'
                }`}
              >
                <RotateCw className="h-4 w-4 mb-1 text-amber-400" />
                <div className="text-xs font-bold">Force Re-route</div>
                <div className="text-[10px] text-slate-400 mt-0.5">Restart engine search</div>
              </button>
            </div>
          </div>

          {/* If Manual Assign selected: Contributor List */}
          {selectedAction === 'manual_assign' && (
            <div>
              <label className="block text-xs font-semibold text-slate-300 uppercase tracking-wider mb-2">
                Choose Assignee (Enforces Max 1 Active Assignee)
              </label>

              {/* Matching Contributors */}
              <div className="space-y-1.5 max-h-56 overflow-y-auto pr-1">
                {matchingContributors.length > 0 && (
                  <div className="text-[11px] font-semibold text-indigo-400 uppercase tracking-wider px-1 pt-1">
                    Matching Expertise ({task.expertiseRequired})
                  </div>
                )}
                {matchingContributors.map((c) => {
                  const isSelected = selectedContributorId === c.id;
                  return (
                    <div
                      key={c.id}
                      onClick={() => setSelectedContributorId(c.id)}
                      className={`p-2.5 rounded-xl border flex items-center justify-between cursor-pointer transition ${
                        isSelected
                          ? 'bg-indigo-600/20 border-indigo-500 text-white'
                          : 'bg-slate-950/80 border-slate-800 hover:border-slate-700 text-slate-300'
                      }`}
                    >
                      <div className="flex items-center space-x-3">
                        <img
                          src={c.avatar}
                          alt={c.name}
                          className="h-8 w-8 rounded-full object-cover border border-slate-700"
                        />
                        <div>
                          <div className="text-xs font-bold flex items-center space-x-1.5">
                            <span>{c.name}</span>
                            <span className="text-[10px] px-1.5 py-0.2 rounded bg-indigo-500/20 text-indigo-300">
                              Matches
                            </span>
                          </div>
                          <div className="text-[11px] text-slate-400">{c.title}</div>
                        </div>
                      </div>
                      <div className="flex items-center space-x-2">
                        <div className="text-[10px] text-slate-400">
                          {c.activeTaskCount || 0} active
                        </div>
                        {isSelected && <Check className="h-4 w-4 text-indigo-400" />}
                      </div>
                    </div>
                  );
                })}

                {/* Non-matching Contributors with Override label */}
                {otherContributors.length > 0 && (
                  <>
                    <div className="text-[11px] font-semibold text-slate-500 uppercase tracking-wider px-1 pt-3">
                      Other Contributors (Operator Override)
                    </div>
                    {otherContributors.map((c) => {
                      const isSelected = selectedContributorId === c.id;
                      return (
                        <div
                          key={c.id}
                          onClick={() => setSelectedContributorId(c.id)}
                          className={`p-2.5 rounded-xl border flex items-center justify-between cursor-pointer transition ${
                            isSelected
                              ? 'bg-amber-600/20 border-amber-500 text-white'
                              : 'bg-slate-950/80 border-slate-800 hover:border-slate-700 text-slate-300'
                          }`}
                        >
                          <div className="flex items-center space-x-3">
                            <img
                              src={c.avatar}
                              alt={c.name}
                              className="h-8 w-8 rounded-full object-cover border border-slate-700"
                            />
                            <div>
                              <div className="text-xs font-bold text-slate-300">{c.name}</div>
                              <div className="text-[11px] text-slate-400">
                                {c.expertise.join(', ')}
                              </div>
                            </div>
                          </div>
                          <div className="flex items-center space-x-2">
                            <span className="text-[10px] text-amber-400/80">Override</span>
                            {isSelected && <Check className="h-4 w-4 text-amber-400" />}
                          </div>
                        </div>
                      );
                    })}
                  </>
                )}
              </div>
            </div>
          )}

          {/* If Cancel Routing selected */}
          {selectedAction === 'cancel_routing' && (
            <div className="p-3.5 rounded-xl bg-rose-950/20 border border-rose-500/30 text-rose-300 text-xs">
              <div className="font-bold flex items-center space-x-1.5 mb-1">
                <AlertCircle className="h-4 w-4" />
                <span>Confirm Abort</span>
              </div>
              <p className="text-rose-300/80 leading-relaxed">
                This will immediately cancel any background routing process. The task will transition to <strong>cancelled</strong> state and will remain in queue until an operator recovers or re-routes it.
              </p>
            </div>
          )}

          {/* Reason / Operator Note */}
          <div>
            <label className="block text-xs font-semibold text-slate-300 uppercase tracking-wider mb-1.5">
              Operator Reason / Audit Note
            </label>
            <input
              type="text"
              value={reason}
              onChange={(e) => setReason(e.target.value)}
              placeholder="e.g. Expedited executive priority / Routing request hanging past threshold..."
              className="w-full px-3.5 py-2.5 rounded-xl bg-slate-950 border border-slate-800 focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500 text-xs text-slate-100 placeholder-slate-500 outline-none transition"
            />
          </div>

          {/* Actions */}
          <div className="pt-3 border-t border-slate-800 flex items-center justify-end space-x-2.5">
            <button
              type="button"
              onClick={onClose}
              className="px-4 py-2 rounded-xl text-xs font-semibold text-slate-400 hover:text-white hover:bg-slate-800 transition cursor-pointer"
            >
              Cancel
            </button>
            <button
              type="submit"
              disabled={submitting || (selectedAction === 'manual_assign' && !selectedContributorId)}
              className="px-5 py-2.5 rounded-xl text-xs font-bold bg-amber-600 hover:bg-amber-500 text-white shadow-lg shadow-amber-600/30 disabled:opacity-50 transition cursor-pointer"
            >
              {submitting ? 'Executing...' : 'Apply Intervention'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Task, Contributor } from '../types.js';
import {
  X,
  RotateCw,
  UserCheck,
  RotateCcw,
  Tag,
  Check,
} from 'lucide-react';

interface RecoverModalProps {
  task: Task | null;
  contributors: Contributor[];
  isOpen: boolean;
  onClose: () => void;
  onRecover: (
    action: 'reroute' | 'manual',
    contributorId?: string,
    reason?: string
  ) => Promise<void>;
}

export const RecoverModal: React.FC<RecoverModalProps> = ({
  task,
  contributors,
  isOpen,
  onClose,
  onRecover,
}) => {
  const [method, setMethod] = useState<'reroute' | 'manual'>('reroute');
  const [selectedContributorId, setSelectedContributorId] = useState<string>('');
  const [reason, setReason] = useState<string>('');
  const [submitting, setSubmitting] = useState<boolean>(false);

  if (!isOpen || !task) return null;

  const matchingContributors = contributors.filter((c) =>
    c.expertise.map((e) => e.toLowerCase()).includes(task.expertiseRequired.toLowerCase())
  );

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (method === 'manual' && !selectedContributorId) return;

    try {
      setSubmitting(true);
      await onRecover(method, selectedContributorId, reason.trim());
      setReason('');
      setSelectedContributorId('');
      onClose();
    } catch (err) {
      console.error(err);
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/75 backdrop-blur-sm animate-in fade-in duration-200">
      <div className="bg-slate-900 border border-slate-800 rounded-2xl w-full max-w-lg shadow-2xl overflow-hidden flex flex-col">
        {/* Header */}
        <div className="p-5 border-b border-slate-800 flex items-center justify-between bg-slate-950/60">
          <div className="flex items-center space-x-2.5">
            <div className="h-8 w-8 rounded-lg bg-sky-500/20 text-sky-400 flex items-center justify-center border border-sky-500/30">
              <RotateCw className="h-4 w-4" />
            </div>
            <div>
              <div className="flex items-center space-x-2">
                <h2 className="text-base font-bold text-white">Recover Task</h2>
                <span className="font-mono text-xs text-slate-400 bg-slate-800 px-2 py-0.5 rounded border border-slate-700">
                  {task.id}
                </span>
              </div>
              <p className="text-xs text-slate-400">
                Recover from {task.state} state and resume routing workflow
              </p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="p-1.5 rounded-lg text-slate-400 hover:text-white hover:bg-slate-800 transition cursor-pointer"
          >
            <X className="h-4 w-4" />
          </button>
        </div>

        {/* Form Body */}
        <form onSubmit={handleSubmit} className="p-6 space-y-4">
          {/* Recovery Strategy Selection */}
          <div>
            <label className="block text-xs font-semibold text-slate-300 uppercase tracking-wider mb-2">
              Recovery Action
            </label>
            <div className="grid grid-cols-2 gap-2">
              <button
                type="button"
                onClick={() => setMethod('reroute')}
                className={`p-3 rounded-xl border text-left transition cursor-pointer ${
