];

export const ContributorsModal: React.FC<ContributorsModalProps> = ({
  contributors,
  isOpen,
  onClose,
  onAddContributor,
}) => {
  const [showAddForm, setShowAddForm] = useState(false);
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [title, setTitle] = useState('');
