import React, { useState, useEffect } from 'react';
import { SimulationConfig } from '../types.js';
import {
  X,
  Sliders,
  AlertTriangle,
  Clock,
  RotateCcw,
  Play,
  Check,
} from 'lucide-react';

interface SimulationConfigModalProps {
  isOpen: boolean;
  onClose: () => void;
  onResetDatabase: () => void;
}

export const SimulationConfigModal: React.FC<SimulationConfigModalProps> = ({
  isOpen,
  onClose,
  onResetDatabase,
}) => {
  const [config, setConfig] = useState<SimulationConfig | null>(null);
  const [minSec, setMinSec] = useState<number>(5);
  const [maxSec, setMaxSec] = useState<number>(20);
  const [probPercent, setProbPercent] = useState<number>(20);
  const [saving, setSaving] = useState(false);
  const [savedSuccess, setSavedSuccess] = useState(false);

  useEffect(() => {
    if (isOpen) {
      fetch('/api/simulation/config')
        .then((res) => res.json())
        .then((data) => {
          setConfig(data);
          setMinSec(Math.round(data.minDurationMs / 1000));
          setMaxSec(Math.round(data.maxDurationMs / 1000));
          setProbPercent(Math.round(data.stuckProbability * 100));
        })
        .catch(console.error);
    }
  }, [isOpen]);

  if (!isOpen) return null;

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      setSaving(true);
      const res = await fetch('/api/simulation/config', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          minDurationMs: minSec * 1000,
          maxDurationMs: maxSec * 1000,
          stuckProbability: probPercent / 100,
        }),
      });
      if (res.ok) {
        setSavedSuccess(true);
        setTimeout(() => setSavedSuccess(false), 2000);
      }
    } catch (err) {
      console.error(err);
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/75 backdrop-blur-sm animate-in fade-in duration-200">
      <div className="bg-slate-900 border border-slate-800 rounded-2xl w-full max-w-lg shadow-2xl overflow-hidden flex flex-col">
        {/* Header */}
        <div className="p-5 border-b border-slate-800 flex items-center justify-between bg-slate-950/60">
          <div className="flex items-center space-x-2.5">
            <div className="h-8 w-8 rounded-lg bg-indigo-500/20 text-indigo-400 flex items-center justify-center border border-indigo-500/30">
              <Sliders className="h-4 w-4" />
            </div>
            <div>
              <h2 className="text-base font-bold text-white">Routing Engine Simulation Parameters</h2>
              <p className="text-xs text-slate-400">
                Configure background request timing and hanging edge case probability
              </p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="p-1.5 rounded-lg text-slate-400 hover:text-white hover:bg-slate-800 transition cursor-pointer"
          >
            <X className="h-4 w-4" />
          </button>
        </div>

        {/* Form Body */}
        <form onSubmit={handleSave} className="p-6 space-y-5">
          {/* Default Challenge Requirements Notice */}
          <div className="p-3.5 rounded-xl bg-slate-950/60 border border-slate-800 text-xs text-slate-300 space-y-1">
            <div className="font-bold text-white">Default Challenge Specification:</div>
            <div>• Normal routing takes between <strong>5 and 20 seconds</strong> to return.</div>
            <div>• <strong>20%</strong> of routing requests never return at all (simulating hanging workers).</div>
          </div>

          {/* Min & Max Duration */}
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-xs font-semibold text-slate-300 uppercase tracking-wider mb-1.5">
                Min Duration (Seconds)
              </label>
              <input
                type="number"
                min={1}
                max={maxSec}
                value={minSec}
                onChange={(e) => setMinSec(Number(e.target.value))}
                className="w-full px-3 py-2 rounded-xl bg-slate-950 border border-slate-800 text-sm text-white outline-none focus:border-indigo-500"
              />
            </div>
            <div>
              <label className="block text-xs font-semibold text-slate-300 uppercase tracking-wider mb-1.5">
                Max Duration (Seconds)
              </label>
              <input
                type="number"
                min={minSec}
                max={60}
                value={maxSec}
                onChange={(e) => setMaxSec(Number(e.target.value))}
                className="w-full px-3 py-2 rounded-xl bg-slate-950 border border-slate-800 text-sm text-white outline-none focus:border-indigo-500"
              />
            </div>
          </div>

          {/* Stuck Probability Slider */}
          <div>
            <div className="flex items-center justify-between mb-1.5">
              <label className="text-xs font-semibold text-slate-300 uppercase tracking-wider">
                Hanging Edge Case Probability
              </label>
              <span className="text-xs font-bold text-amber-400">{probPercent}%</span>
            </div>
            <input
              type="range"
              min={0}
              max={100}
              step={5}
              value={probPercent}
              onChange={(e) => setProbPercent(Number(e.target.value))}
              className="w-full accent-amber-400 cursor-pointer"
            />
            <div className="flex justify-between text-[10px] text-slate-500 mt-1">
              <span>0% (Always returns)</span>
              <span className="text-amber-400 font-bold">20% (Default Spec)</span>
              <span>100% (Always hangs)</span>
            </div>
          </div>

          {/* Reset to Spec Defaults button */}
          <div className="pt-2 flex items-center justify-between text-xs">
            <button
              type="button"
              onClick={() => {
                setMinSec(5);
                setMaxSec(20);
                setProbPercent(20);
              }}
              className="text-slate-400 hover:text-white underline cursor-pointer"
            >
              Reset to 5-20s & 20% spec defaults
            </button>
            <button
              type="button"
              onClick={onResetDatabase}
              className="text-rose-400 hover:text-rose-300 flex items-center space-x-1 cursor-pointer"
            >
              <RotateCcw className="h-3 w-3" />
              <span>Reset all tasks</span>
            </button>
          </div>

          {/* Actions */}
          <div className="pt-3 border-t border-slate-800 flex items-center justify-end space-x-2.5">
            <button
              type="button"
              onClick={onClose}
              className="px-4 py-2 rounded-xl text-xs font-semibold text-slate-400 hover:text-white hover:bg-slate-800 transition cursor-pointer"
            >
              Cancel
            </button>
            <button
              type="submit"
              disabled={saving}
              className="flex items-center space-x-1.5 px-5 py-2.5 rounded-xl text-xs font-bold bg-indigo-600 hover:bg-indigo-500 text-white shadow-lg shadow-indigo-600/30 transition cursor-pointer"
            >
              {savedSuccess ? (
                <>
                  <Check className="h-3.5 w-3.5 text-emerald-300" />
                  <span>Saved!</span>
                </>
              ) : (
                <span>{saving ? 'Saving...' : 'Save Parameters'}</span>
              )}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

import React, { useEffect, useState, useCallback } from 'react';
import { Task, Contributor, SystemStats } from './types.js';
import { Navbar } from './components/Navbar.js';
import { MetricsBar } from './components/MetricsBar.js';
import { TaskCard } from './components/TaskCard.js';
import { TaskHistoryModal } from './components/TaskHistoryModal.js';
import { NewTaskModal } from './components/NewTaskModal.js';
import { InterveneModal } from './components/InterveneModal.js';
import { RecoverModal } from './components/RecoverModal.js';
import { ContributorsModal } from './components/ContributorsModal.js';
import { SimulationConfigModal } from './components/SimulationConfigModal.js';
import {
  Search,
  Filter,
  RefreshCw,
  Plus,
  AlertTriangle,
  Inbox,
  Sparkles,
} from 'lucide-react';

export function App() {
  const [tasks, setTasks] = useState<Task[]>([]);
  const [contributors, setContributors] = useState<Contributor[]>([]);
  const [stats, setStats] = useState<SystemStats | null>(null);
  const [connected, setConnected] = useState<boolean>(false);
  const [loading, setLoading] = useState<boolean>(true);

  // Filters
  const [activeFilter, setActiveFilter] = useState<string>('all');
  const [searchQuery, setSearchQuery] = useState<string>('');
  const [expertiseFilter, setExpertiseFilter] = useState<string>('all');

  // Modals
  const [newTaskOpen, setNewTaskOpen] = useState<boolean>(false);
  const [contributorsOpen, setContributorsOpen] = useState<boolean>(false);
  const [simulationOpen, setSimulationOpen] = useState<boolean>(false);
  const [historyTask, setHistoryTask] = useState<Task | null>(null);
  const [interveneTask, setInterveneTask] = useState<Task | null>(null);
  const [recoverTask, setRecoverTask] = useState<Task | null>(null);

  // Notification Banner
  const [toastMessage, setToastMessage] = useState<{ text: string; type: 'info' | 'success' | 'warn' } | null>(null);

  const showToast = (text: string, type: 'info' | 'success' | 'warn' = 'success') => {
    setToastMessage({ text, type });
    setTimeout(() => {
      setToastMessage((prev) => (prev?.text === text ? null : prev));
    }, 4000);
  };

  // Fetch initial data
  const fetchData = useCallback(async () => {
    try {
      const [tasksRes, contribRes] = await Promise.all([
        fetch('/api/tasks'),
        fetch('/api/contributors'),
      ]);
      const tasksData = await tasksRes.json();
      const contribData = await contribRes.json();

      setTasks(tasksData.tasks || []);
      setStats(tasksData.stats || null);
      setContributors(contribData.contributors || []);
    } catch (err) {
      console.error('Error fetching data:', err);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  // Connect to SSE event stream for real-time reactivity
  useEffect(() => {
    const eventSource = new EventSource('/api/events');

    eventSource.onopen = () => {
      setConnected(true);
    };

    eventSource.onmessage = (event) => {
      try {
        const payload = JSON.parse(event.data);
        if (payload.type === 'TASK_CREATED' || payload.type === 'TASK_UPDATED') {
          const { task, stats: updatedStats } = payload.data;
          setTasks((prev) => {
            const index = prev.findIndex((t) => t.id === task.id);
            if (index >= 0) {
              const updated = [...prev];
              updated[index] = task;
              return updated;
            } else {
              return [task, ...prev];
            }
          });
          if (updatedStats) setStats(updatedStats);

          // Update active history modal if open for this task
          setHistoryTask((current) => (current && current.id === task.id ? task : current));
        } else if (payload.type === 'SYSTEM_RESET') {
          fetchData();
        } else if (payload.type === 'CONTRIBUTOR_UPDATED') {
          fetch('/api/contributors')
            .then((res) => res.json())
            .then((data) => setContributors(data.contributors || []));
        }
      } catch (err) {
        console.error('Error parsing SSE event:', err);
      }
    };

    eventSource.onerror = () => {
      setConnected(false);
    };

    return () => {
      eventSource.close();
    };
  }, [fetchData]);

  // Operator Handlers
  const handleCreateTask = async (data: {
    title: string;
    description: string;
    expertiseRequired: string;
    autoRoute: boolean;
    forceStuck: boolean;
  }) => {
    const res = await fetch('/api/tasks', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(data),
    });
    const result = await res.json();
    if (res.ok) {
      showToast(
        data.forceStuck
          ? `Created task '${result.task.title}' (Simulating 20% hanging edge case)`
          : `Created task '${result.task.title}' and submitted for routing!`,
        data.forceStuck ? 'warn' : 'success'
      );
      fetchData();
    } else {
      alert(result.error || 'Failed to create task');
    }
  };

  const handleIntervene = async (
    action: 'manual_assign' | 'cancel_routing' | 'force_reroute',
    contributorId?: string,
    reason?: string
  ) => {
    if (!interveneTask) return;
    const res = await fetch(`/api/tasks/${interveneTask.id}/intervene`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ action, contributorId, reason, operatorName: 'Human Operator' }),
    });
    const result = await res.json();
    if (res.ok) {
      showToast(`Operator intervention applied to ${interveneTask.id}`, 'info');
      fetchData();
    } else {
      alert(result.error || 'Intervention failed');
    }
  };

  const handleRecover = async (
    action: 'reroute' | 'manual',
    contributorId?: string,
    reason?: string
  ) => {
    if (!recoverTask) return;
    const res = await fetch(`/api/tasks/${recoverTask.id}/recover`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ action, contributorId, reason, operatorName: 'Human Operator' }),
    });
    const result = await res.json();
    if (res.ok) {
      showToast(`Task ${recoverTask.id} recovered successfully!`, 'success');
      fetchData();
    } else {
      alert(result.error || 'Recovery failed');
    }
  };

  const handleContributorAccept = async (taskId: string) => {
    const res = await fetch(`/api/tasks/${taskId}/contributor-action`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ action: 'accept' }),
    });
    const result = await res.json();
    if (res.ok) {
      showToast(`Contributor accepted assignment for ${taskId}. Routing finished!`, 'success');
      fetchData();
    }
  };

  const handleContributorDecline = async (taskId: string) => {
    const res = await fetch(`/api/tasks/${taskId}/contributor-action`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        action: 'decline',
        reason: 'Current workload capacity exceeded',
      }),
    });
    const result = await res.json();
    if (res.ok) {
      showToast(`Contributor declined assignment for ${taskId}. Ready for operator recovery.`, 'warn');
      fetchData();
    }
  };

  const handleSeedStuckDemo = async () => {
    const res = await fetch('/api/system/seed-demo-routing', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ type: 'stuck' }),
    });
    const result = await res.json();
    if (res.ok) {
      showToast(
        `Spawned hanging background routing task ${result.task.id} (20% Edge Case Demo)`,
        'warn'
      );
      fetchData();
    }
  };

  const handleResetDatabase = async () => {
    if (confirm('Reset system and tasks to initial demo state?')) {
      const res = await fetch('/api/system/reset', { method: 'POST' });
      if (res.ok) {
        showToast('System database reset to initial demonstration state.', 'info');
        fetchData();
      }
    }
  };

  const handleAddContributor = async (data: {
    name: string;
    email: string;
    title: string;
    expertise: string[];
  }) => {
    const res = await fetch('/api/contributors', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(data),
    });
    if (res.ok) {
      showToast(`Added contributor ${data.name}!`, 'success');
      const contribRes = await fetch('/api/contributors');
      const contribData = await contribRes.json();
      setContributors(contribData.contributors || []);
    }
  };

  // Filter & Search processing
  const filteredTasks = tasks.filter((task) => {
    // 1. Status Filter
    if (activeFilter === 'routing' && task.state !== 'routing') return false;
    if (activeFilter === 'assigned' && task.state !== 'assigned') return false;
    if (activeFilter === 'accepted' && task.state !== 'accepted') return false;
    if (
      activeFilter === 'needs_recovery' &&
      task.state !== 'failed' &&
      task.state !== 'declined'
    )
      return false;
    if (activeFilter === 'cancelled' && task.state !== 'cancelled') return false;

    // 2. Expertise Filter
    if (
      expertiseFilter !== 'all' &&
      task.expertiseRequired.toLowerCase() !== expertiseFilter.toLowerCase()
    ) {
      return false;
    }

    // 3. Search query
    if (searchQuery.trim()) {
      const q = searchQuery.toLowerCase();
      const matchTitle = task.title.toLowerCase().includes(q);
      const matchId = task.id.toLowerCase().includes(q);
      const matchDesc = task.description.toLowerCase().includes(q);
      const matchAssignee =
        task.activeAssignee && task.activeAssignee.name.toLowerCase().includes(q);
      const matchExp = task.expertiseRequired.toLowerCase().includes(q);

      if (!matchTitle && !matchId && !matchDesc && !matchAssignee && !matchExp) {
        return false;
      }
    }

    return true;
  });

  // Extract all unique expertise categories from tasks & contributors
  const allExpertiseAreas = Array.from(
    new Set([
      'Finance',
      'Healthcare',
      'Data Analysis',
      'Operations',
      'Legal',
      'Security',
      ...tasks.map((t) => t.expertiseRequired),
      ...contributors.flatMap((c) => c.expertise),
    ])
  );

  return (
    <div className="min-h-screen bg-slate-950 text-slate-100 flex flex-col font-sans selection:bg-indigo-500 selection:text-white">
      {/* Top Navbar */}
      <Navbar
        connected={connected}
        onOpenNewTask={() => setNewTaskOpen(true)}
        onOpenContributors={() => setContributorsOpen(true)}
        onOpenSimulation={() => setSimulationOpen(true)}
        onSeedStuckDemo={handleSeedStuckDemo}
        onResetDatabase={handleResetDatabase}
      />

      {/* Toast Notification */}
      {toastMessage && (
        <div className="fixed bottom-6 right-6 z-50 animate-in slide-in-from-bottom-5 duration-200">
          <div
            className={`px-4 py-3 rounded-xl shadow-xl border flex items-center space-x-2 text-xs font-semibold ${
              toastMessage.type === 'warn'
                ? 'bg-amber-950/90 text-amber-200 border-amber-500/40'
                : toastMessage.type === 'info'
                ? 'bg-sky-950/90 text-sky-200 border-sky-500/40'
                : 'bg-emerald-950/90 text-emerald-200 border-emerald-500/40'
            }`}
          >
            <Sparkles className="h-4 w-4 shrink-0" />
            <span>{toastMessage.text}</span>
          </div>
        </div>
      )}

      {/* Main Content Area */}
      <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-6">
        {/* Real-time Metrics Bar */}
        <MetricsBar
          stats={stats}
          activeFilter={activeFilter}
          onSelectFilter={setActiveFilter}
        />

        {/* Filter & Controls Toolbar */}
        <div className="p-4 rounded-2xl bg-slate-900/60 border border-slate-800 mb-6 flex flex-wrap items-center justify-between gap-3">
          {/* Status Tabs */}
          <div className="flex flex-wrap items-center gap-1.5">
            {[
              { id: 'all', label: 'All Tasks' },
              { id: 'routing', label: 'In Routing' },
              { id: 'assigned', label: 'Assigned' },
              { id: 'accepted', label: 'Accepted' },
              { id: 'needs_recovery', label: 'Needs Recovery' },
              { id: 'cancelled', label: 'Cancelled' },
            ].map((tab) => {
              const active = activeFilter === tab.id;
              return (
                <button
                  key={tab.id}
                  onClick={() => setActiveFilter(tab.id)}
                  className={`px-3 py-1.5 rounded-lg text-xs font-semibold transition cursor-pointer ${
                    active
                      ? 'bg-indigo-600 text-white shadow-md shadow-indigo-600/30'
                      : 'bg-slate-950/70 text-slate-400 hover:text-slate-200 hover:bg-slate-800'
                  }`}
                >
                  {tab.label}
                </button>
              );
            })}
          </div>

          {/* Search & Expertise Filter */}
          <div className="flex items-center space-x-2.5">
            {/* Search Input */}
            <div className="relative">
              <Search className="h-3.5 w-3.5 text-slate-500 absolute left-3 top-1/2 -translate-y-1/2" />
              <input
                type="text"
                placeholder="Search tasks or assignees..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="pl-8 pr-3 py-1.5 rounded-lg bg-slate-950 border border-slate-800 focus:border-indigo-500 text-xs text-white placeholder-slate-500 outline-none w-48 sm:w-60 transition"
              />
            </div>

            {/* Expertise Dropdown */}
            <div className="relative">
              <select
                value={expertiseFilter}
                onChange={(e) => setExpertiseFilter(e.target.value)}
                className="px-3 py-1.5 rounded-lg bg-slate-950 border border-slate-800 text-xs text-slate-300 outline-none focus:border-indigo-500 cursor-pointer"
              >
                <option value="all">All Expertise Areas</option>
                {allExpertiseAreas.map((exp) => (
                  <option key={exp} value={exp}>
                    {exp}
                  </option>
                ))}
              </select>
            </div>

            {/* Refresh */}
            <button
              onClick={fetchData}
              title="Refresh data"
              className="p-2 rounded-lg bg-slate-950 border border-slate-800 text-slate-400 hover:text-white hover:border-slate-700 transition cursor-pointer"
            >
              <RefreshCw className="h-3.5 w-3.5" />
            </button>
          </div>
        </div>

        {/* Task Grid */}
        {loading ? (
          <div className="py-20 text-center text-slate-400 flex flex-col items-center">
            <RefreshCw className="h-8 w-8 animate-spin text-indigo-400 mb-3" />
            <p className="text-sm font-medium">Connecting to task routing engine...</p>
          </div>
        ) : filteredTasks.length === 0 ? (
          <div className="py-20 text-center rounded-2xl border border-dashed border-slate-800 bg-slate-900/30 p-8 flex flex-col items-center">
            <div className="h-12 w-12 rounded-full bg-slate-800/80 flex items-center justify-center text-slate-500 mb-3">
              <Inbox className="h-6 w-6" />
            </div>
            <h3 className="text-base font-bold text-white mb-1">No tasks matching criteria</h3>
            <p className="text-xs text-slate-400 max-w-sm mb-4">
              Try adjusting your filter or search query, or create a new task to submit to the routing engine.
            </p>
            <button
              onClick={() => setNewTaskOpen(true)}
              className="px-4 py-2 rounded-lg text-xs font-bold bg-indigo-600 hover:bg-indigo-500 text-white flex items-center space-x-1.5 cursor-pointer shadow-lg shadow-indigo-600/20"
            >
              <Plus className="h-4 w-4" />
              <span>Create Task</span>
            </button>
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {filteredTasks.map((task) => (
              <TaskCard
                key={task.id}
                task={task}
                onInspectHistory={(t) => setHistoryTask(t)}
                onIntervene={(t) => setInterveneTask(t)}
                onRecover={(t) => setRecoverTask(t)}
                onContributorAccept={handleContributorAccept}
                onContributorDecline={handleContributorDecline}
              />
            ))}
          </div>
        )}
      </main>

      {/* Modals */}
      <NewTaskModal
        isOpen={newTaskOpen}
        onClose={() => setNewTaskOpen(false)}
        onSubmit={handleCreateTask}
      />

      <TaskHistoryModal
        task={historyTask}
        onClose={() => setHistoryTask(null)}
        onIntervene={(t) => {
          setHistoryTask(null);
          setInterveneTask(t);
        }}
        onRecover={(t) => {
          setHistoryTask(null);
          setRecoverTask(t);
        }}
      />

      <InterveneModal
        task={interveneTask}
        contributors={contributors}
        isOpen={Boolean(interveneTask)}
        onClose={() => setInterveneTask(null)}
        onExecute={handleIntervene}
      />

      <RecoverModal
        task={recoverTask}
        contributors={contributors}
        isOpen={Boolean(recoverTask)}
        onClose={() => setRecoverTask(null)}
        onRecover={handleRecover}
      />

      <ContributorsModal
        contributors={contributors}
        isOpen={contributorsOpen}
        onClose={() => setContributorsOpen(false)}
        onAddContributor={handleAddContributor}
      />

      <SimulationConfigModal
        isOpen={simulationOpen}
        onClose={() => setSimulationOpen(false)}
        onResetDatabase={handleResetDatabase}
      />
    </div>
  );
}

