          <button
            onClick={onClose}
            className="p-1 rounded-md text-muted-foreground hover:text-foreground hover:bg-accent transition cursor-pointer"
          >
            <X className="h-4 w-4" />
          </button>
        </div>

        {/* Content Body: Task Context & Timeline */}
        <div className="p-6 overflow-y-auto space-y-5 flex-1">
          {/* Active Assignee summary if assigned */}
          {task.activeAssignee && (
            <div className="p-3.5 rounded-lg bg-muted/30 border border-border flex items-center justify-between">
              <div className="flex items-center space-x-3">
                <img
                  src={task.activeAssignee.avatar}
                  alt={task.activeAssignee.name}
                  className="h-8 w-8 rounded-full object-cover border border-border"
                />
                <div>
                  <div className="text-xs font-semibold text-foreground flex items-center space-x-1.5">
                    <span>{task.activeAssignee.name}</span>
                    <span className="text-[10px] px-1.5 py-0.2 rounded bg-emerald-500/10 text-emerald-700 dark:text-emerald-300 border border-emerald-500/20">
                      Active Assignee (Max 1)
                    </span>
                  </div>
                  <div className="text-[11px] text-muted-foreground">
                    {task.activeAssignee.title} • {task.activeAssignee.email}
                  </div>
                </div>
              </div>

              {task.assignedAt && (
                <div className="text-right text-[11px] text-muted-foreground">
                  <div className="font-medium text-foreground">Assigned</div>
                  <div>{formatDateTime(task.assignedAt)}</div>
                </div>
              )}
            </div>
          )}

          {/* Audit Log / Timeline Section */}
          <div>
            <div className="flex items-center justify-between mb-3.5">
              <h3 className="text-xs font-semibold text-foreground uppercase tracking-wider flex items-center space-x-1.5">
                <ShieldCheck className="h-3.5 w-3.5 text-primary" />
                <span>Audit Trail & State History</span>
              </h3>
              <span className="text-[11px] text-muted-foreground font-mono">
                {task.history ? task.history.length : 0} event(s)
              </span>
            </div>

            {/* Timeline Tree */}
            <div className="relative pl-5 space-y-4 before:absolute before:left-2.5 before:top-2 before:bottom-2 before:w-px before:bg-border">
              {task.history && task.history.length > 0 ? (
                task.history.map((entry, index) => {
                  const actorConfig = getActorConfig(entry.actor);
                  const isLatest = index === task.history.length - 1;

                  return (
                    <div key={entry.id || index} className="relative group">
                      {/* Timeline Dot */}
                      <div
                        className={`absolute -left-5 top-1 h-5 w-5 rounded-full border flex items-center justify-center bg-card ${
                          isLatest
                            ? 'border-primary shadow-xs'
                            : 'border-border'
                        }`}
                      >
                        {renderActorIcon(entry.actor)}
                      </div>

                      {/* Event Card */}
                      <div className="bg-card border border-border rounded-lg p-3 hover:border-border/80 transition shadow-xs">
                        {/* Header: Actor, Action, State transition */}
                        <div className="flex flex-wrap items-center justify-between gap-1.5 mb-1.5">
                          <div className="flex items-center space-x-2">
                            <span
                              className={`text-[10px] font-medium px-1.5 py-0.5 rounded border ${actorConfig.badge}`}
                            >
                              {entry.actorName || actorConfig.name}
                            </span>
                            <span className="text-xs font-mono font-medium text-foreground">
                              {entry.action}
                            </span>
                          </div>

                          {/* State Transition Badge */}
                          <div className="flex items-center space-x-1 text-[11px] font-mono">
                            {entry.previousState && (
                              <>
                                <span className="text-muted-foreground">{entry.previousState}</span>
                                <ArrowRight className="h-3 w-3 text-muted-foreground" />
                              </>
                            )}
                            <span className="font-semibold text-primary px-1.5 py-0.5 rounded bg-primary/10 border border-primary/20">
                              {entry.newState}
                            </span>
                          </div>
                        </div>

                        {/* Event Narrative Details */}
                        <p className="text-xs text-muted-foreground leading-relaxed">
                          {entry.details}
                        </p>

                        {/* Metadata tags if present */}
                        {entry.metadata && Object.keys(entry.metadata).length > 0 && (
                          <div className="mt-2 pt-1.5 border-t border-border/60 flex flex-wrap gap-1.5 text-[10px] font-mono text-muted-foreground">
                            {Object.entries(entry.metadata).map(([k, v]) => (
                              <span
                                key={k}
                                className="px-1.5 py-0.5 rounded bg-muted text-muted-foreground border border-border"
                              >
                                {k}: {typeof v === 'boolean' ? (v ? 'true' : 'false') : String(v)}
                              </span>
                            ))}
                          </div>
                        )}

                        {/* Timestamp */}
                        <div className="mt-1.5 text-[10px] text-muted-foreground flex items-center space-x-1">
                          <Clock className="h-3 w-3" />
                          <span>{formatDateTime(entry.timestamp)}</span>
                          <span>•</span>
                          <span>{formatRelativeTime(entry.timestamp)}</span>
                        </div>
                      </div>
                    </div>
                  );
                })
              ) : (
                <div className="text-xs text-muted-foreground italic">No history records found.</div>
              )}
            </div>
          </div>
        </div>

        {/* Footer */}
        <div className="p-3.5 border-t border-border bg-muted/20 flex items-center justify-between">
          <div className="text-[11px] text-muted-foreground">
            Audit logs are immutable and sequentially verified.
          </div>
          <button
            onClick={onClose}
            className="px-3.5 py-1.5 rounded-md text-xs font-medium border border-input bg-background hover:bg-accent text-foreground transition cursor-pointer"
          >
            Close
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { X, Sparkles, AlertTriangle, Send } from 'lucide-react';

interface NewTaskModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSubmit: (data: {
    title: string;
    description: string;
    expertiseRequired: string;
    autoRoute: boolean;
    forceStuck: boolean;
  }) => Promise<void>;
}

const PRESET_EXPERTISE = [
  'Finance',
  'Healthcare',
  'Data Analysis',
  'Operations',
  'Legal',
  'Security',
];

export const NewTaskModal: React.FC<NewTaskModalProps> = ({
  isOpen,
  onClose,
  onSubmit,
}) => {
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [expertiseRequired, setExpertiseRequired] = useState('Finance');
  const [customExpertise, setCustomExpertise] = useState('');
  const [isCustom, setIsCustom] = useState(false);
  const [autoRoute, setAutoRoute] = useState(true);
  const [forceStuck, setForceStuck] = useState(false);
  const [submitting, setSubmitting] = useState(false);

  if (!isOpen) return null;

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const finalExpertise = isCustom ? customExpertise.trim() : expertiseRequired;
    if (!title.trim() || !finalExpertise) return;

    try {
      setSubmitting(true);
      await onSubmit({
        title: title.trim(),
        description: description.trim(),
        expertiseRequired: finalExpertise,
        autoRoute,
        forceStuck,
      });
      setTitle('');
      setDescription('');
      setExpertiseRequired('Finance');
      setCustomExpertise('');
      setIsCustom(false);
      setForceStuck(false);
      onClose();
    } catch (err) {
      console.error(err);
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-background/80 backdrop-blur-xs animate-in fade-in duration-150">
      <div className="bg-card text-card-foreground border border-border rounded-xl w-full max-w-lg shadow-lg overflow-hidden flex flex-col">
        {/* Header */}
        <div className="p-5 border-b border-border flex items-center justify-between bg-muted/20">
          <div className="flex items-center space-x-2.5">
            <div className="h-7 w-7 rounded-md bg-primary/10 text-primary flex items-center justify-center border border-primary/20">
              <Sparkles className="h-3.5 w-3.5" />
            </div>
            <div>
              <h2 className="text-sm font-semibold text-foreground tracking-tight">Create New Task</h2>
              <p className="text-xs text-muted-foreground">
                Define required expertise domain and dispatch
              </p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="p-1 rounded-md text-muted-foreground hover:text-foreground hover:bg-accent transition cursor-pointer"
          >
            <X className="h-4 w-4" />
          </button>
        </div>

        {/* Form Body */}
        <form onSubmit={handleSubmit} className="p-5 space-y-4">
          {/* Title */}
          <div>
            <label className="block text-xs font-medium text-foreground mb-1.5">
              Task Title *
            </label>
            <input
              type="text"
              required
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              placeholder="e.g. Q4 Hospital Revenue Cycle Audit"
              className="w-full px-3 py-2 rounded-lg bg-background border border-input focus:border-ring focus:ring-1 focus:ring-ring text-xs text-foreground placeholder:text-muted-foreground outline-none transition"
            />
          </div>

          {/* Description */}
          <div>
            <label className="block text-xs font-medium text-foreground mb-1.5">
              Description
            </label>
            <textarea
              rows={2}
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              placeholder="Detail specific deliverables, constraints, or context..."
              className="w-full px-3 py-2 rounded-lg bg-background border border-input focus:border-ring focus:ring-1 focus:ring-ring text-xs text-foreground placeholder:text-muted-foreground outline-none transition resize-none"
            />
          </div>

          {/* Required Expertise Area */}
          <div>
            <label className="block text-xs font-medium text-foreground mb-1.5">
              Required Expertise Area *
            </label>
            <div className="grid grid-cols-3 gap-1.5 mb-2">
              {PRESET_EXPERTISE.map((exp) => {
                const selected = !isCustom && expertiseRequired === exp;
                return (
                  <button
                    key={exp}
                    type="button"
                    onClick={() => {
                      setIsCustom(false);
                      setExpertiseRequired(exp);
                    }}
                    className={`px-2.5 py-1.5 rounded-md text-xs font-medium border transition text-left cursor-pointer ${
                      selected
                        ? 'bg-primary text-primary-foreground border-primary shadow-xs'
                        : 'bg-background border-input text-muted-foreground hover:text-foreground hover:bg-accent'
                    }`}
                  >
                    {exp}
                  </button>
                );
              })}
            </div>

            {/* Custom Expertise option */}
            <div className="flex items-center space-x-2 mt-1.5">
              <input
                type="text"
                placeholder="Or specify custom expertise (e.g. Quantum Computing)..."
                value={customExpertise}
                onFocus={() => setIsCustom(true)}
                onChange={(e) => {
                  setIsCustom(true);
                  setCustomExpertise(e.target.value);
                }}
                className={`flex-1 px-3 py-1.5 rounded-lg text-xs bg-background border outline-none transition ${
                  isCustom
                    ? 'border-ring ring-1 ring-ring text-foreground'
                    : 'border-input text-muted-foreground'
                }`}
              />
            </div>
            <p className="text-[11px] text-muted-foreground mt-1">
              If no registered contributor matches this expertise, the engine reports "No match found".
            </p>
          </div>

          {/* Routing Options */}
          <div className="pt-2 border-t border-border space-y-2">
            <label className="flex items-center space-x-2 cursor-pointer">
              <input
                type="checkbox"
                checked={autoRoute}
                onChange={(e) => setAutoRoute(e.target.checked)}
                className="h-3.5 w-3.5 rounded border-input bg-background text-primary focus:ring-ring"
              />
              <span className="text-xs text-foreground font-medium">
                Submit immediately to background routing engine (5–20s window)
              </span>
            </label>

            {/* Force Stuck Testing Option */}
            {autoRoute && (
              <label className="flex items-start space-x-2 p-2.5 rounded-lg bg-amber-500/10 border border-amber-500/25 cursor-pointer">
                <input
                  type="checkbox"
                  checked={forceStuck}
                  onChange={(e) => setForceStuck(e.target.checked)}
                  className="h-3.5 w-3.5 mt-0.5 rounded border-amber-500 text-amber-500 focus:ring-amber-500"
                />
                <div>
                  <span className="text-xs font-semibold text-amber-900 dark:text-amber-200 flex items-center space-x-1">
                    <AlertTriangle className="h-3 w-3 inline text-amber-500" />
                    <span>Explicitly Simulate 20% Hanging Edge Case</span>
                  </span>
                  <span className="text-[11px] text-amber-800/80 dark:text-amber-300/80 block leading-tight mt-0.5">
                    Request will hang indefinitely without returning, allowing immediate demonstration of operator intervention.
                  </span>
                </div>
              </label>
            )}
          </div>

          {/* Actions */}
          <div className="pt-2 flex items-center justify-end space-x-2">
            <button
              type="button"
              onClick={onClose}
              className="px-3.5 py-1.5 rounded-md text-xs font-medium border border-input bg-background hover:bg-accent text-foreground transition cursor-pointer"
            >
              Cancel
            </button>
            <button
              type="submit"
              disabled={submitting || !title.trim()}
              className="flex items-center space-x-1.5 px-4 py-1.5 rounded-md text-xs font-medium bg-primary text-primary-foreground hover:bg-primary/90 shadow-xs disabled:opacity-50 transition cursor-pointer"
            >
              <Send className="h-3.5 w-3.5" />
              <span>{submitting ? 'Creating...' : autoRoute ? 'Create & Route' : 'Create Draft'}</span>
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Task, Contributor } from '../types.js';
import {
  X,
  Zap,
  UserCheck,
  Ban,
  RotateCw,
  AlertCircle,
  Check,
} from 'lucide-react';

interface InterveneModalProps {
  task: Task | null;
  contributors: Contributor[];
  isOpen: boolean;
  onClose: () => void;
  onExecute: (
    action: 'manual_assign' | 'cancel_routing' | 'force_reroute',
    contributorId?: string,
    reason?: string
  ) => Promise<void>;
}

export const InterveneModal: React.FC<InterveneModalProps> = ({
  task,
  contributors,
  isOpen,
  onClose,
  onExecute,
}) => {
  const [selectedAction, setSelectedAction] = useState<
    'manual_assign' | 'cancel_routing' | 'force_reroute'
  >('manual_assign');
  const [selectedContributorId, setSelectedContributorId] = useState<string>('');
  const [reason, setReason] = useState<string>('');
  const [submitting, setSubmitting] = useState<boolean>(false);

  if (!isOpen || !task) return null;

  const matchingContributors = contributors.filter((c) =>
    c.expertise.map((e) => e.toLowerCase()).includes(task.expertiseRequired.toLowerCase())
  );
  const otherContributors = contributors.filter(
    (c) =>
      !c.expertise.map((e) => e.toLowerCase()).includes(task.expertiseRequired.toLowerCase())
  );

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (selectedAction === 'manual_assign' && !selectedContributorId) return;

    try {
      setSubmitting(true);
      await onExecute(selectedAction, selectedContributorId, reason.trim());
      setReason('');
      setSelectedContributorId('');
      onClose();
    } catch (err) {
      console.error(err);
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-background/80 backdrop-blur-xs animate-in fade-in duration-150">
      <div className="bg-card text-card-foreground border border-border rounded-xl w-full max-w-lg shadow-lg overflow-hidden flex flex-col max-h-[85vh]">
        {/* Header */}
        <div className="p-5 border-b border-border flex items-center justify-between bg-muted/20">
          <div className="flex items-center space-x-2.5">
            <div className="h-7 w-7 rounded-md bg-amber-500/10 text-amber-600 dark:text-amber-400 flex items-center justify-center border border-amber-500/20">
              <Zap className="h-3.5 w-3.5" />
            </div>
            <div>
              <div className="flex items-center space-x-2">
                <h2 className="text-sm font-semibold text-foreground tracking-tight">Operator Intervention</h2>
                <span className="font-mono text-[11px] text-muted-foreground bg-muted px-1.5 py-0.2 rounded border border-border">
                  {task.id}
                </span>
              </div>
              <p className="text-xs text-muted-foreground">
                Override active routing or manually reassign specialist
              </p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="p-1 rounded-md text-muted-foreground hover:text-foreground hover:bg-accent transition cursor-pointer"
          >
            <X className="h-4 w-4" />
          </button>
        </div>

        {/* Task Summary Banner */}
        <div className="px-5 py-2.5 bg-muted/30 border-b border-border flex items-center justify-between text-xs">
          <div className="truncate max-w-[260px]">
            <span className="text-muted-foreground">Task: </span>
            <span className="font-medium text-foreground">{task.title}</span>
          </div>
          <div className="flex items-center space-x-1.5 shrink-0">
            <span className="text-muted-foreground">Expertise: </span>
            <span className="font-medium text-primary px-2 py-0.5 rounded bg-primary/10 border border-primary/20">
              {task.expertiseRequired}
            </span>
          </div>
        </div>

        {/* Form Body */}
        <form onSubmit={handleSubmit} className="p-5 overflow-y-auto space-y-4 flex-1">
          {/* Action Choice Tabs */}
          <div>
            <label className="block text-xs font-medium text-foreground mb-1.5">
              Select Action
            </label>
            <div className="grid grid-cols-3 gap-2">
              <button
                type="button"
                onClick={() => setSelectedAction('manual_assign')}
                className={`p-2.5 rounded-lg border text-left transition cursor-pointer ${
                  selectedAction === 'manual_assign'
                    ? 'bg-primary text-primary-foreground border-primary shadow-xs'
                    : 'bg-background border-input text-muted-foreground hover:text-foreground hover:bg-accent'
                }`}
              >
                <UserCheck className="h-3.5 w-3.5 mb-1" />
                <div className="text-xs font-semibold">Manual Assign</div>
                <div className="text-[10px] opacity-80 mt-0.5">Pick specialist</div>
              </button>

              <button
                type="button"
                onClick={() => setSelectedAction('cancel_routing')}
                className={`p-2.5 rounded-lg border text-left transition cursor-pointer ${
                  selectedAction === 'cancel_routing'
                    ? 'bg-destructive text-destructive-foreground border-destructive shadow-xs'
                    : 'bg-background border-input text-muted-foreground hover:text-foreground hover:bg-accent'
                }`}
              >
                <Ban className="h-3.5 w-3.5 mb-1" />
                <div className="text-xs font-semibold">Cancel Routing</div>
                <div className="text-[10px] opacity-80 mt-0.5">Abort request</div>
              </button>

              <button
                type="button"
                onClick={() => setSelectedAction('force_reroute')}
                className={`p-2.5 rounded-lg border text-left transition cursor-pointer ${
                  selectedAction === 'force_reroute'
                    ? 'bg-amber-600 text-white border-amber-600 shadow-xs'
                    : 'bg-background border-input text-muted-foreground hover:text-foreground hover:bg-accent'
                }`}
              >
                <RotateCw className="h-3.5 w-3.5 mb-1" />
