            <button
              type="submit"
              disabled={submitting || (method === 'manual' && !selectedContributorId)}
              className="px-4 py-1.5 rounded-md text-xs font-medium bg-primary text-primary-foreground hover:bg-primary/90 shadow-xs disabled:opacity-50 transition cursor-pointer"
            >
              {submitting ? 'Recovering...' : method === 'reroute' ? 'Recover & Route Again' : 'Recover & Assign'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Contributor } from '../types.js';
import {
  X,
  Users,
  Plus,
} from 'lucide-react';

interface ContributorsModalProps {
  contributors: Contributor[];
  isOpen: boolean;
  onClose: () => void;
  onAddContributor: (contributor: {
    name: string;
    email: string;
    title: string;
    expertise: string[];
  }) => Promise<void>;
}

const PRESET_EXPERTISE = [
  'Finance',
  'Healthcare',
  'Data Analysis',
  'Operations',
  'Legal',
  'Security',
];

export const ContributorsModal: React.FC<ContributorsModalProps> = ({
  contributors,
  isOpen,
  onClose,
  onAddContributor,
}) => {
  const [showAddForm, setShowAddForm] = useState(false);
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [title, setTitle] = useState('');
  const [selectedExpertise, setSelectedExpertise] = useState<string[]>(['Finance']);
  const [customTag, setCustomTag] = useState('');
  const [submitting, setSubmitting] = useState(false);

  if (!isOpen) return null;

  const toggleExpertise = (exp: string) => {
    if (selectedExpertise.includes(exp)) {
      if (selectedExpertise.length > 1) {
        setSelectedExpertise(selectedExpertise.filter((e) => e !== exp));
      }
    } else {
      setSelectedExpertise([...selectedExpertise, exp]);
    }
  };

  const handleAddCustom = () => {
    const trimmed = customTag.trim();
    if (trimmed && !selectedExpertise.includes(trimmed)) {
      setSelectedExpertise([...selectedExpertise, trimmed]);
      setCustomTag('');
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!name.trim() || selectedExpertise.length === 0) return;

    try {
      setSubmitting(true);
      await onAddContributor({
        name: name.trim(),
        email: email.trim(),
        title: title.trim(),
        expertise: selectedExpertise,
      });
      setName('');
      setEmail('');
      setTitle('');
      setSelectedExpertise(['Finance']);
      setShowAddForm(false);
    } catch (err) {
      console.error(err);
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-background/80 backdrop-blur-xs animate-in fade-in duration-150">
      <div className="bg-card text-card-foreground border border-border rounded-xl w-full max-w-xl shadow-lg overflow-hidden flex flex-col max-h-[85vh]">
        {/* Header */}
        <div className="p-5 border-b border-border flex items-center justify-between bg-muted/20">
